const e="ledgerdashboard",t="LedgerDashboard",a="../SmartLedgerAI-JobPrep/LedgerDashboard",s={expressRoutes:[{dir:"server/src",gate:'app\\.use\\("/api", \\(req, res, next\\) =>'}],sql:[{dir:"db",database:"LedgerDashboard"}],reactRoutes:"client/src/App.jsx"},n=[{id:"start",title:{en:"Getting started",fa:"شروع"}},{id:"security",title:{en:"Security and data safety",fa:"امنیت و سلامت داده"}},{id:"ledger",title:{en:"Applications and the pipeline",fa:"درخواست‌ها و pipeline"}},{id:"ai",title:{en:"With Claude: scoring, building, asking",fa:"با Claude: امتیاز، ساخت، پرسش"}},{id:"truth",title:{en:"The truth bank and its health",fa:"بانک حقیقت و سلامتش"}},{id:"frontend",title:{en:"Frontend (React)",fa:"فرانت‌اند (React)"}},{id:"data",title:{en:"Data: CSV or SQL Server",fa:"داده: CSV یا SQL Server"}}],r=[{id:"run",group:"start",title:{en:"Run it: on the PC or in Docker",fa:"اجرا: روی PC یا در Docker"},files:["README.md","server/index.js","server/src/config.js","Dockerfile","server/.env.example"],en:[{id:"local",h:"One process, one port",p:["`cd server && npm start` serves the API and the built React app on http://localhost:4310, so no second terminal is needed. The data is not in the repo: it is the sibling `JobSearch/engine/` folder (the ledger, the pipeline events, the application folders, the fact bank) and the Python résumé engine there, which the server runs.","With no password set, it listens on 127.0.0.1 only. That is not a default you can forget to change: asked to listen anywhere else without a password, it refuses to start."],examples:["host","start"]},{id:"docker",h:"The image",p:["The image has Node, Python with python-docx, LibreOffice (Word to PDF) and git, runs as the unprivileged `node` user, and never contains the job-search data: that is mounted at `/data/JobSearch`. `NODE_ENV=production` turns on Secure cookies and hides internal error messages."],examples:["image"]},{id:"server",h:"On the server",p:["Control Panel runs it at ledger.arashkeshtgar.ca with a password and a session secret, bound to the server's loopback behind Caddy, and with the SQL Server store. The nightly job search on the PC reaches it through an SSH tunnel with an API token instead of a login. How the server is set up is in Control Panel's topics (deploy-vps)."]}],fa:[{id:"local",h:"یک process، یک پورت",p:["`cd server && npm start` هم API و هم اپ React build‌شده را روی http://localhost:4310 سرو می‌کند، پس ترمینال دوم لازم نیست. داده در repo نیست: پوشه‌ی کناری `JobSearch/engine/` است (ledger، رویدادهای pipeline، پوشه‌ی درخواست‌ها، fact bank) و موتور رزومه‌ی Python همان‌جا، که سرور اجرایش می‌کند.","بدون رمز، فقط روی 127.0.0.1 گوش می‌دهد. این پیش‌فرضی نیست که یادت برود عوضش کنی: اگر بخواهی بدون رمز جای دیگری گوش بدهد، اصلاً بالا نمی‌آید."],examples:["host","start"]},{id:"docker",h:"image",p:["image، Node، Python با python-docx، LibreOffice (Word به PDF) و git دارد، با کاربر بی‌امتیاز `node` اجرا می‌شود، و هیچ‌وقت داده‌ی جست‌وجوی کار را ندارد: آن در `/data/JobSearch` mount می‌شود. `NODE_ENV=production` کوکی Secure را روشن می‌کند و پیام خطاهای داخلی را پنهان."],examples:["image"]},{id:"server",h:"روی سرور",p:["Control Panel آن را روی ledger.arashkeshtgar.ca اجرا می‌کند، با رمز و session secret، بسته به loopback سرور پشت Caddy، و با store از نوع SQL Server. جست‌وجوی شبانه‌ی کار روی PC از یک تونل SSH با API token به آن می‌رسد نه با ورود. این‌که سرور چطور راه افتاده در topicهای Control Panel آمده (deploy-vps)."]}],examples:{host:{title:{en:"No password, no other host",fa:"بدون رمز، بدون host دیگر"},lang:"javascript",file:"server/src/config.js",from:'const host = env.HOST || (password ? "0.0.0.0" : "127.0.0.1");',lines:7},start:{title:{en:"An unsafe setup stops at start",fa:"تنظیم ناامن موقع بالا آمدن متوقف می‌شود"},lang:"javascript",file:"server/index.js",from:"let cfg;",lines:9},image:{title:{en:"The image's settings",fa:"تنظیمات image"},lang:"dockerfile",file:"Dockerfile",from:"ENV NODE_ENV=production",lines:11}},quiz:[{q:{en:"With no password set, why does the server refuse to start when asked to listen on another host?",fa:"وقتی رمزی تنظیم نشده، چرا سرور حاضر نیست روی host دیگری گوش بدهد و اصلاً بالا نمی‌آید؟"},options:{en:["Because Docker cannot bind 0.0.0.0","Because without a password the 127.0.0.1 binding is the only protection, so listening elsewhere would expose the data to anyone","Because the React build only works on localhost"],fa:["چون Docker نمی‌تواند به 0.0.0.0 bind شود","چون بدون رمز، bind روی 127.0.0.1 تنها محافظ است و گوش دادن جای دیگر داده را بی‌رمز در اختیار همه می‌گذارد","چون build ری‌اکت فقط روی localhost کار می‌کند"]},answer:1,why:{en:"Locally there is no login at all; the loopback address is what keeps other machines out, so the server would rather not start than run exposed.",fa:"در حالت محلی هیچ login‌ای نیست؛ آدرس loopback است که ماشین‌های دیگر را بیرون نگه می‌دارد، پس سرور ترجیح می‌دهد بالا نیاید تا اینکه باز و بی‌محافظ اجرا شود."}},{q:{en:"What does `NODE_ENV=production` in the image turn on?",fa:"`NODE_ENV=production` در image چه چیزی را روشن می‌کند؟"},options:{en:["The SQL Server store","Secure cookies, and internal error messages hidden from responses","The Vite dev origin in the allowed list"],fa:["store مربوط به SQL Server","cookieهای Secure، و پنهان شدن پیام خطاهای داخلی از پاسخ‌ها","origin مربوط به Vite dev در فهرست مجاز"]},answer:1,why:{en:"Production marks the session cookie Secure and replaces unexpected error messages (which can contain server paths) with a generic one; the store is chosen separately by `STORE`.",fa:"production کوکی session را Secure می‌کند و پیام خطاهای پیش‌بینی‌نشده (که می‌توانند مسیرهای سرور را داشته باشند) را با پیامی کلی عوض می‌کند؛ store جداگانه با `STORE` انتخاب می‌شود."}},{q:{en:"How does the nightly job search on the PC talk to the deployed dashboard?",fa:"جست‌وجوی شبانه‌ی کار روی PC چطور با داشبورد مستقر روی سرور حرف می‌زند؟"},options:{en:["It fills in the login form with the password","It calls the public URL with no authentication","Through an SSH tunnel, with an API token instead of a login"],fa:["فرم login را با رمز پر می‌کند","URL عمومی را بدون هیچ احرازی صدا می‌زند","از راه یک SSH tunnel، با یک API token به جای login"]},answer:2,why:{en:"A script cannot fill a login form, so the server accepts a bearer token as a session; the tunnel reaches the loopback-bound server.",fa:"اسکریپت نمی‌تواند فرم login را پر کند، پس سرور یک bearer token را به جای session می‌پذیرد؛ tunnel به سروری می‌رسد که روی loopback گوش می‌دهد."}}]},{id:"tests",group:"start",title:{en:"Tests, CI and releases",fa:"تست‌ها، CI و releaseها"},files:["server/test/api.test.js","server/test/fixture.js",".github/workflows/ci.yml",".github/workflows/release.yml","server/test/sqlTestDb.js"],en:[{id:"api",h:"The real app, a copy of the data",p:["`npm test` (Vitest) runs the real Express app from `createApp(config, deps)` against a temporary copy of the data layout. Claude is a fake passed in `deps`, and the engine scripts are stand-ins, so analyze → build, timeouts and the build lock are tested without spending anything. The tests read like the rules: a foreign website is refused, a delete lands on the right row after another row was removed, a guessed email is refused."],examples:["origin"]},{id:"fixture",h:"A throwaway data folder and a fake Claude",p:['`makeDataDir()` builds a fresh temporary copy of the `JobSearch/engine` layout for every test: two applications with their folders, `ledger.csv`, `pipeline.csv`, the stages file, a gap dictionary, one fact file and a recruiter list. The real data is never touched, and every test starts from the same known rows, so "a delete lands on the right row after another row was removed" can be checked exactly.',"The Python engine is replaced by tiny scripts that the fixture runs with Node itself (`python: process.execPath`), so the real asynchronous build path, its timeouts and the build lock all run without Python or LibreOffice installed. The fake Claude returns a `tool_use` block and pushes each request into `calls`. That is what lets a test check what was sent (the tool is `strict`, the system prompt has `cache_control`) and, just as important, that nothing was sent: when the spending brake refuses a script, `calls` stays empty."],examples:["fake"]},{id:"ci",h:"CI with a real SQL Server",p:["GitHub Actions starts a throwaway SQL Server container, so the same suite also runs against the SQL store: each run creates and drops its own database. Then the client is linted and built, and the Docker image built.","The API suite is wrapped in `describe.each(KINDS)`: the same requests and the same expectations run once against the CSV files and once against SQL Server, seeded from the same fixture through the real CSV-to-SQL migration. So a behaviour that differs between the two stores fails a test, and the migration itself is exercised on every run. On a PC without `TEST_SQL_SERVER` configured, only the CSV half runs. One more detail came from flaky runs: `listen(0)` on Windows sometimes got a port that `fetch()` refuses outright (5060, 6000...), so the test server re-listens until it gets one fetch will talk to."],examples:["ci","kinds"]},{id:"release",h:"A tag is a release",p:["Pushing a tag like `v1.2.0` publishes a GitHub release with notes generated from the merged pull requests and the built web app attached."],examples:["release"]}],fa:[{id:"api",h:"اپ واقعی، یک کپی از داده",p:["`npm test` (Vitest) اپ واقعی Express را از `createApp(config, deps)` روی یک کپی موقت از ساختار داده اجرا می‌کند. Claude یک fake است که در `deps` داده می‌شود، و اسکریپت‌های موتور جانشین دارند، پس analyze → build، timeoutها و قفل build بدون خرج کردن چیزی تست می‌شوند. تست‌ها مثل خود قانون‌ها خوانده می‌شوند: سایت غریبه رد می‌شود، حذف بعد از حذف یک ردیف دیگر روی ردیف درست می‌نشیند، ایمیل حدسی رد می‌شود."],examples:["origin"]},{id:"fixture",h:"یک پوشه‌ی داده‌ی دورریختنی و یک Claude جعلی",p:["`makeDataDir()` برای هر تست یک کپی تازه و موقت از چیدمان `JobSearch/engine` می‌سازد: دو درخواست با پوشه‌هایشان، `ledger.csv`، `pipeline.csv`، فایل مراحل، یک دیکشنری gap، یک فایل fact و یک فهرست recruiter. داده‌ی واقعی هیچ‌وقت دست نمی‌خورد و هر تست از همان ردیف‌های شناخته‌شده شروع می‌کند، پس می‌شود دقیق بررسی کرد که «حذف، بعد از پاک شدن یک ردیف دیگر، روی ردیف درست می‌نشیند».","موتور Python با اسکریپت‌های کوچکی عوض شده که fixture آن‌ها را با خود Node اجرا می‌کند (`python: process.execPath`)، پس مسیر واقعی و ناهمگام build، timeoutها و قفل build بدون نصب Python یا LibreOffice اجرا می‌شوند. Claude جعلی یک بلوک `tool_use` برمی‌گرداند و هر درخواست را در `calls` می‌گذارد. همین است که به تست اجازه می‌دهد ببیند چه فرستاده شده (tool از نوع `strict` است، system prompt دارای `cache_control` است) و به همان اندازه مهم، ببیند چیزی فرستاده نشده: وقتی ترمز هزینه یک اسکریپت را رد می‌کند، `calls` خالی می‌ماند."],examples:["fake"]},{id:"ci",h:"CI با یک SQL Server واقعی",p:["GitHub Actions یک container دورریختنی SQL Server بالا می‌آورد، پس همین مجموعه روی store SQL هم اجرا می‌شود: هر اجرا دیتابیس خودش را می‌سازد و پاک می‌کند. بعد client، lint و build می‌شود، و image داکر ساخته می‌شود.","مجموعه‌ی تست API داخل `describe.each(KINDS)` است: همان درخواست‌ها و همان انتظارها یک بار روی فایل‌های CSV و یک بار روی SQL Server اجرا می‌شوند، که از همان fixture و از راه migration واقعی CSV به SQL پر شده است. پس رفتاری که بین دو store فرق کند یک تست را می‌شکند، و خود migration هم در هر اجرا آزموده می‌شود. روی PC‌ای که `TEST_SQL_SERVER` تنظیم نشده، فقط نیمه‌ی CSV اجرا می‌شود. یک نکته‌ی دیگر از اجراهای ناپایدار آمد: `listen(0)` روی Windows گاهی پورتی می‌گرفت که `fetch()` اصلاً قبولش نمی‌کند (5060، 6000...)، پس سرور تست آن‌قدر دوباره listen می‌کند تا پورتی بگیرد که fetch با آن حرف بزند."],examples:["ci","kinds"]},{id:"release",h:"یک tag یعنی یک release",p:["push کردن tagی مثل `v1.2.0` یک GitHub release منتشر می‌کند، با یادداشت‌هایی ساخته از pull requestهای merge‌شده و اپ وب build‌شده به‌عنوان پیوست."],examples:["release"]}],examples:{origin:{title:{en:"A foreign website can't read the ledger",fa:"سایت غریبه ledger را نمی‌خواند"},lang:"javascript",file:"server/test/api.test.js",from:'it("refuses a read from a foreign website"',lines:7},ci:{title:{en:"A SQL Server for the tests",fa:"یک SQL Server برای تست‌ها"},lang:"yaml",file:".github/workflows/ci.yml",from:"services:",lines:15},release:{title:{en:"Package and publish",fa:"بسته‌بندی و انتشار"},lang:"yaml",file:".github/workflows/release.yml",from:"- name: Package",lines:6},fake:{title:{en:"A fake Claude that records every request",fa:"یک Claude جعلی که هر درخواست را ثبت می‌کند"},lang:"javascript",file:"server/test/fixture.js",from:"export function fakeAnthropic(inputFor) {",lines:13},kinds:{title:{en:"The whole suite, once per store",fa:"کل مجموعه، یک بار برای هر store"},lang:"javascript",file:"server/test/api.test.js",from:"// The whole API suite runs once per store",to:"const KINDS"}},quiz:[{q:{en:"Why is Claude passed in as a fake through `deps` rather than called for real?",fa:"چرا Claude به‌صورت جعلی از راه `deps` داده می‌شود و واقعاً صدا زده نمی‌شود؟"},options:{en:["So analyze → build runs without spending anything, and each test can inspect exactly what was (or was not) sent","Because the Anthropic SDK cannot run inside Vitest","So the tests can run against SQL Server"],fa:["تا analyze → build بدون هیچ هزینه‌ای اجرا شود و هر تست دقیقاً ببیند چه چیزی فرستاده شد (یا نشد)","چون Anthropic SDK داخل Vitest اجرا نمی‌شود","تا تست‌ها روی SQL Server اجرا شوند"]},answer:0,why:{en:"The fake records every request in `calls`, so a test can assert on the request shape or that the brake made no call at all.",fa:"نسخه‌ی جعلی هر درخواست را در `calls` نگه می‌دارد، پس تست می‌تواند شکل درخواست را بسنجد یا اینکه ترمز هیچ فراخوانی‌ای نکرده است."}},{q:{en:"What happens to the SQL half of the suite on a PC where `TEST_SQL_SERVER` is not set?",fa:"روی PC‌ای که `TEST_SQL_SERVER` تنظیم نشده، نیمه‌ی SQL مجموعه‌ی تست چه می‌شود؟"},options:{en:["The whole suite fails","Only the CSV store runs; the SQL runs need a configured server","It falls back to an in-memory database"],fa:["کل مجموعه شکست می‌خورد","فقط store مربوط به CSV اجرا می‌شود؛ اجرای SQL به یک سرور تنظیم‌شده نیاز دارد","به یک پایگاه داده‌ی درون حافظه برمی‌گردد"]},answer:1,why:{en:'`KINDS` is `["csv", "sql"]` only when a SQL Server is configured; CI always provides one in a service container.',fa:'`KINDS` فقط وقتی SQL Server تنظیم شده `["csv", "sql"]` است؛ CI همیشه یکی را در یک service container فراهم می‌کند.'}},{q:{en:"Why do the stand-in engine scripts run with `process.execPath`?",fa:"چرا اسکریپت‌های جایگزین موتور با `process.execPath` اجرا می‌شوند؟"},options:{en:["To make the build faster in production","Because Python is not allowed in CI","So the real child-process build path is tested without needing Python or LibreOffice"],fa:["تا build در production سریع‌تر شود","چون Python در CI مجاز نیست","تا مسیر واقعی build با child process آزموده شود بدون اینکه Python یا LibreOffice لازم باشد"]},answer:2,why:{en:"The server still spawns a child process exactly as in real use; only the program it runs is Node with a one-line script.",fa:"سرور همچنان دقیقاً مثل استفاده‌ی واقعی یک child process می‌سازد؛ فقط برنامه‌ای که اجرا می‌کند Node با یک اسکریپت یک‌خطی است."}}]},{id:"login",group:"security",title:{en:"Two modes: local, or a password",fa:"دو حالت: محلی، یا با رمز"},files:["server/src/config.js","server/src/security.js","server/src/app.js"],en:[{id:"endpoints",h:"The only routes open without a session",p:["Everything else under `/api` sits behind the gate below. Locally, with no password, there is no gate and no login at all: the 127.0.0.1 binding is the protection."],data:{kind:"endpoints",only:["login","logout","session"]}},{id:"config",h:"Settings checked before anything runs",p:["`loadConfig` reads every environment setting in one place and throws on a dangerous combination: a password shorter than 12 characters, a session secret shorter than 32 or equal to the password, an API token without a password. The server would rather not start than run exposed."],examples:["secret"]},{id:"session",h:"A signed cookie, nothing in memory",p:["The session is a signed `httpOnly` cookie (`cookie-session`), `SameSite=Lax`, Secure in production, valid 30 days. Nothing is kept on the server, so sessions survive restarts and redeploys, and changing `SESSION_SECRET` signs every device out."],examples:["cookie"]},{id:"guess",h:"Against guessing",p:["The password is compared in constant time: both sides are hashed with SHA-256 first, so even the length can't leak. Five wrong tries lock that IP out for 15 minutes, with a `Retry-After`."],examples:["compare","login"]},{id:"token",h:"Scripts: a bearer token",p:["The nightly job search can't fill a login form, so `Authorization: Bearer <API_TOKEN>` counts as a session. A browser never sends that header on its own, so it opens nothing to other websites."],examples:["token","gate"]}],fa:[{id:"endpoints",h:"تنها routeهایی که بدون session باز هستند",p:["بقیه‌ی `/api` پشت دروازه‌ای است که پایین آمده. در حالت محلی، بدون رمز، نه دروازه‌ای هست و نه ورودی: بسته بودن به 127.0.0.1 خودش محافظت است."],data:{kind:"endpoints",only:["login","logout","session"]}},{id:"config",h:"تنظیمات قبل از اجرای هر چیز چک می‌شوند",p:["`loadConfig` همه‌ی تنظیمات محیطی را در یک جا می‌خواند و با یک ترکیب خطرناک خطا می‌اندازد: رمز کوتاه‌تر از ۱۲ کاراکتر، session secret کوتاه‌تر از ۳۲ یا برابر رمز، API token بدون رمز. سرور ترجیح می‌دهد بالا نیاید تا این‌که باز اجرا شود."],examples:["secret"]},{id:"session",h:"کوکی امضاشده، هیچ چیز در حافظه",p:["session یک کوکی `httpOnly` امضاشده است (`cookie-session`)، `SameSite=Lax`، در production با Secure، و ۳۰ روز معتبر. روی سرور هیچ چیز نگه داشته نمی‌شود، پس session‌ها از restart و redeploy جان سالم به در می‌برند، و عوض کردن `SESSION_SECRET` همه‌ی دستگاه‌ها را بیرون می‌کند."],examples:["cookie"]},{id:"guess",h:"در برابر حدس زدن",p:["رمز با زمان ثابت مقایسه می‌شود: هر دو طرف اول با SHA-256 hash می‌شوند، پس حتی طولش هم لو نمی‌رود. پنج تلاش غلط آن IP را ۱۵ دقیقه قفل می‌کند، با `Retry-After`."],examples:["compare","login"]},{id:"token",h:"اسکریپت‌ها: یک bearer token",p:["جست‌وجوی شبانه‌ی کار نمی‌تواند فرم ورود را پر کند، پس `Authorization: Bearer <API_TOKEN>` یک session حساب می‌شود. مرورگر هیچ‌وقت خودش این هدر را نمی‌فرستد، پس چیزی به روی سایت‌های دیگر باز نمی‌کند."],examples:["token","gate"]}],examples:{secret:{title:{en:"The session secret's rules",fa:"قانون‌های session secret"},lang:"javascript",file:"server/src/config.js",from:"if (sessionSecret.length < MIN_SESSION_SECRET_LENGTH) {",lines:10},cookie:{title:{en:"The session cookie",fa:"کوکی session"},lang:"javascript",file:"server/src/app.js",from:"cookieSession({",lines:8},compare:{title:{en:"Same length, same time",fa:"طول یکسان، زمان یکسان"},lang:"javascript",file:"server/src/security.js",from:"export function passwordMatches(candidate, expected) {",lines:5},login:{title:{en:"Sign-in with the limiter",fa:"ورود با محدودکننده"},lang:"javascript",file:"server/src/app.js",from:'app.post("/api/login", (req, res) => {',lines:18},token:{title:{en:"A bearer token for scripts",fa:"bearer token برای اسکریپت‌ها"},lang:"javascript",file:"server/src/app.js",from:"const hasApiToken = (req) => {",lines:5},gate:{title:{en:"The gate",fa:"دروازه"},lang:"javascript",file:"server/src/app.js",from:'app.use("/api", (req, res, next) => {',lines:5}},quiz:[{q:{en:"Why are both passwords hashed with SHA-256 before `timingSafeEqual`?",fa:"چرا هر دو رمز پیش از `timingSafeEqual` با SHA-256 هش می‌شوند؟"},options:{en:["So the buffers have the same length and neither timing nor a length mismatch leaks anything","So the password can be stored hashed in the database","Because SHA-256 is faster than comparing strings"],fa:["تا بافرها هم‌طول شوند و نه زمان مقایسه و نه اختلاف طول چیزی لو ندهد","تا رمز به‌صورت هش در پایگاه داده ذخیره شود","چون SHA-256 از مقایسه‌ی رشته‌ها سریع‌تر است"]},answer:0,why:{en:"`timingSafeEqual` needs equal-length buffers; hashing gives that, so an early length check can not reveal the real password length.",fa:"`timingSafeEqual` بافرهای هم‌طول می‌خواهد؛ هش همین را می‌دهد، پس بررسی زودهنگام طول نمی‌تواند طول رمز واقعی را آشکار کند."}},{q:{en:"What happens to every signed-in device when `SESSION_SECRET` is changed?",fa:"وقتی `SESSION_SECRET` عوض شود، برای همه‌ی دستگاه‌های وارد شده چه اتفاقی می‌افتد؟"},options:{en:["Nothing, sessions are stored on the server","They are all signed out, because their cookies no longer verify","They stay signed in for 30 more days"],fa:["هیچ، sessionها روی سرور نگه داشته می‌شوند","همه خارج می‌شوند، چون امضای cookieشان دیگر معتبر نیست","تا ۳۰ روز دیگر وارد می‌مانند"]},answer:1,why:{en:"The session lives only in the signed cookie; a new secret means no existing cookie verifies.",fa:"session فقط در cookie امضاشده زندگی می‌کند؛ secret تازه یعنی هیچ cookie موجودی تأیید نمی‌شود."}},{q:{en:"Why does accepting `Authorization: Bearer <API_TOKEN>` not open the API to other websites?",fa:"چرا پذیرفتن `Authorization: Bearer <API_TOKEN>` API را به روی سایت‌های دیگر باز نمی‌کند؟"},options:{en:["Because the token is sent in the URL","Because the token is checked only on GET requests","Because a browser never adds that header by itself; a page would have to know the token"],fa:["چون token در URL فرستاده می‌شود","چون token فقط روی درخواست‌های GET بررسی می‌شود","چون مرورگر هیچ‌وقت خودش آن header را اضافه نمی‌کند؛ صفحه باید token را بداند"]},answer:2,why:{en:"Unlike a cookie, which the browser attaches automatically, the header must be set explicitly with the secret value.",fa:"برخلاف cookie که مرورگر خودکار ضمیمه می‌کند، این header باید صریحاً و با مقدار محرمانه گذاشته شود."}}]},{id:"origin",group:"security",title:{en:"No website may call the API",fa:"هیچ سایتی API را صدا نمی‌زند"},files:["server/src/security.js","server/src/config.js","server/test/api.test.js"],en:[{id:"why",h:"Reads too, not only writes",p:["The dashboard is often used with no password, on 127.0.0.1. A page on any website open in the same browser could still send requests to localhost:4310. So every `/api` request carrying a foreign `Origin` gets 403, reads as well as writes: no other site can read the ledger, delete a row or start a paid build.","The guard is mounted on `/api` before every route, so it runs before the login gate and before any handler. A foreign request is turned away with no `Access-Control-Allow-Origin` header at all, which means the browser would not hand the response to the page even if something had gone through. The tests check both halves: a foreign read gets 403 with no CORS header, and a foreign `DELETE` is already refused at its `OPTIONS` preflight, so the real request is never sent."],examples:["guard","preflight"]},{id:"allowed",h:"Who may",p:["Same origin (the app served by this server) and requests with no `Origin` (curl, scripts) pass. The only foreign origin allowed is the Vite dev server, and only outside production; it is echoed back, never `*`.","Echoing the one allowed origin, rather than answering `*`, matters because the response also says `Access-Control-Allow-Credentials: true`, and browsers refuse a wildcard together with credentials. `Vary: Origin` tells any cache in between that the answer depends on who asked. The preflight answer lists only the methods the API uses (GET, POST, PATCH, DELETE) and the `Content-Type` header.","In production the dev origins are dropped from the list, since the built app is served by this same server and needs no CORS. Any other origin has to be named explicitly in `CORS_ORIGINS`; with that variable empty, the list adds nothing."],examples:["dev","allowed","extra"]}],fa:[{id:"why",h:"خواندن هم، نه فقط نوشتن",p:["داشبورد اغلب بدون رمز و روی 127.0.0.1 استفاده می‌شود. صفحه‌ای از هر سایتی که در همان مرورگر باز است هنوز می‌تواند به localhost:4310 درخواست بفرستد. پس هر درخواست `/api` که `Origin` غریبه دارد 403 می‌گیرد، چه خواندن چه نوشتن: هیچ سایت دیگری نمی‌تواند ledger را بخواند، ردیفی را حذف کند یا یک build پولی راه بیندازد.","این guard پیش از همه‌ی routeها روی `/api` نصب شده، پس پیش از دروازه‌ی login و پیش از هر handler اجرا می‌شود. درخواست غریبه بدون هیچ header `Access-Control-Allow-Origin` برگردانده می‌شود، یعنی حتی اگر چیزی رد شده بود، مرورگر پاسخ را به صفحه نمی‌داد. تست‌ها هر دو نیمه را بررسی می‌کنند: خواندن از سایت غریبه 403 بدون header CORS می‌گیرد، و `DELETE` از سایت غریبه همان‌جا در preflight `OPTIONS` رد می‌شود، پس درخواست اصلی هرگز فرستاده نمی‌شود."],examples:["guard","preflight"]},{id:"allowed",h:"چه کسی اجازه دارد",p:["همان origin (اپی که همین سرور سرو می‌کند) و درخواست‌های بدون `Origin` (curl، اسکریپت‌ها) رد می‌شوند. تنها origin غریبه‌ی مجاز Vite dev server است، و فقط بیرون از production؛ خودش برگردانده می‌شود، هیچ‌وقت `*`.","برگرداندن همان یک origin مجاز به جای `*` مهم است، چون پاسخ `Access-Control-Allow-Credentials: true` هم دارد و مرورگرها wildcard را همراه credentials نمی‌پذیرند. `Vary: Origin` به هر cache میان‌راهی می‌گوید پاسخ به این بستگی دارد که چه کسی پرسیده. پاسخ preflight فقط متدهایی را که API به کار می‌برد (GET، POST، PATCH، DELETE) و header `Content-Type` را فهرست می‌کند.","در production، originهای dev از فهرست حذف می‌شوند، چون اپ build‌شده را همین سرور سرو می‌کند و به CORS نیازی ندارد. هر origin دیگری باید صریحاً در `CORS_ORIGINS` نام برده شود؛ اگر این متغیر خالی باشد، چیزی به فهرست اضافه نمی‌شود."],examples:["dev","allowed","extra"]}],examples:{guard:{title:{en:"The cross-origin guard",fa:"نگهبان cross-origin"},lang:"javascript",file:"server/src/security.js",from:"export function originGuard(allowedOrigins) {",lines:21},dev:{title:{en:"The dev server's origins",fa:"originهای dev server"},lang:"javascript",file:"server/src/config.js",from:"const DEV_ORIGINS",lines:1},allowed:{title:{en:"Only outside production",fa:"فقط بیرون از production"},lang:"javascript",file:"server/src/config.js",from:"allowedOrigins: [",lines:1},extra:{title:{en:"More origins, only when configured",fa:"originهای بیشتر، فقط وقتی تنظیم شوند"},lang:"javascript",file:"server/src/config.js",from:'const extraOrigins = (env.CORS_ORIGINS || "")',lines:4},preflight:{title:{en:"A foreign delete is stopped at the preflight",fa:"حذف از سایت غریبه در preflight متوقف می‌شود"},lang:"javascript",file:"server/test/api.test.js",from:'it("refuses a delete preflight from a foreign website"',lines:6}},quiz:[{q:{en:"Why does the guard refuse foreign reads too, not only writes?",fa:"چرا guard خواندن از سایت غریبه را هم رد می‌کند، نه فقط نوشتن را؟"},options:{en:["Because GET requests are slower","Because a page on any site in the same browser could otherwise read the ledger from localhost:4310","Because Express cannot tell reads from writes"],fa:["چون درخواست‌های GET کندترند","چون در غیر این صورت صفحه‌ای از هر سایتی در همان مرورگر می‌توانست ledger را از localhost:4310 بخواند","چون Express نمی‌تواند خواندن را از نوشتن تشخیص دهد"]},answer:1,why:{en:"Locally there is often no password, so the origin check is what keeps another website from exfiltrating the data.",fa:"در حالت محلی اغلب رمزی نیست، پس بررسی origin است که نمی‌گذارد سایت دیگری داده را بیرون بکشد."}},{q:{en:"Why is the allowed origin echoed back instead of answering `Access-Control-Allow-Origin: *`?",fa:"چرا origin مجاز عیناً برگردانده می‌شود و پاسخ `Access-Control-Allow-Origin: *` داده نمی‌شود؟"},options:{en:["Because `*` would allow every website, and browsers refuse `*` together with credentials","Because `*` is not valid in Express","Because the Vite dev server only accepts its own name"],fa:["چون `*` به همه‌ی سایت‌ها اجازه می‌داد، و مرورگرها `*` را همراه credentials نمی‌پذیرند","چون `*` در Express معتبر نیست","چون Vite dev server فقط نام خودش را قبول می‌کند"]},answer:0,why:{en:"The answer also allows credentials, which a wildcard cannot be combined with, and only the one listed origin should be trusted.",fa:"پاسخ credentials را هم مجاز می‌کند که با wildcard ترکیب‌شدنی نیست، و فقط همان origin فهرست‌شده باید مورد اعتماد باشد."}},{q:{en:"A request arrives with no `Origin` header at all (curl, a script). What does the guard do?",fa:"درخواستی بدون هیچ header `Origin` می‌رسد (curl، یک اسکریپت). guard چه می‌کند؟"},options:{en:["Refuses it with 403","Asks for a preflight first","Lets it pass to the next middleware, where the login gate still applies"],fa:["با 403 ردش می‌کند","اول یک preflight می‌خواهد","می‌گذارد به middleware بعدی برود، جایی که دروازه‌ی login هنوز اعمال می‌شود"]},answer:2,why:{en:"A request with no `Origin` is not a cross-site browser request; protecting it is the job of the password or the loopback binding.",fa:"درخواست بدون `Origin` درخواست بین‌سایتی مرورگر نیست؛ محافظت از آن کار رمز یا bind روی loopback است."}}]},{id:"safety",group:"security",title:{en:"Files that can't be damaged",fa:"فایل‌هایی که خراب نمی‌شوند"},files:["server/src/paths.js","server/src/csv.js","server/src/process.js","server/src/app.js"],en:[{id:"folders",h:"Every folder resolved inside applications/",p:["An application is addressed by its folder name (`2026-09-13__Company__Role`), never by row position, so an edit or a delete can't land on the wrong row after the ledger changes. Before any read, write or delete, the name is checked (letters, digits, dot, underscore, dash, no `..`) and resolved strictly inside `applications/`: a value from a request can never point at the fact bank, the scripts or `applications/` itself."],examples:["name","resolve"]},{id:"atomic",h:"Atomic writes, and Excel",p:["`ledger.csv` is rewritten through a temp file and a rename, so a crash leaves the old file or the new one, never half of one. On Windows, a file Excel has open refuses the rename: that becomes a 423 saying to close it in Excel, instead of a failure halfway."],examples:["atomic","locked"]},{id:"process",h:"Python and LibreOffice with timeouts",p:["`validate.py` and `build.py` run as child processes without blocking the event loop (other requests keep being answered during a render), and are killed with their whole process tree after 30 s and 180 s: a hung LibreOffice can't hang the server."],examples:["timer","kill"]},{id:"errors",h:"Errors with the right status",p:["Known errors map to their status (423 locked file, 400 unsafe folder or value the database refused, 429 and 502 from Claude); anything else is a 500 whose message, which can include server paths, is logged but not sent in production."],examples:["errors"]}],fa:[{id:"folders",h:"هر پوشه داخل applications/ resolve می‌شود",p:["هر درخواست با اسم پوشه‌اش شناخته می‌شود (`2026-09-13__Company__Role`)، هیچ‌وقت با شماره‌ی ردیف، پس ویرایش یا حذف بعد از تغییر ledger روی ردیف غلط نمی‌نشیند. قبل از هر خواندن، نوشتن یا حذف، اسم چک می‌شود (حرف، رقم، نقطه، زیرخط، خط تیره، بدون `..`) و دقیقاً داخل `applications/` resolve می‌شود: مقداری که از درخواست آمده هیچ‌وقت نمی‌تواند به fact bank، اسکریپت‌ها یا خود `applications/` اشاره کند."],examples:["name","resolve"]},{id:"atomic",h:"نوشتن اتمیک، و Excel",p:["`ledger.csv` از راه یک فایل موقت و rename بازنویسی می‌شود، پس crash یا فایل قدیمی را باقی می‌گذارد یا فایل تازه را، هیچ‌وقت نصفش را. در Windows، فایلی که Excel باز کرده rename را رد می‌کند: این یک 423 می‌شود که می‌گوید در Excel ببندش، نه شکستی در نیمه‌ی راه."],examples:["atomic","locked"]},{id:"process",h:"Python و LibreOffice با timeout",p:["`validate.py` و `build.py` به‌صورت child process اجرا می‌شوند بی‌آن‌که event loop را قفل کنند (درخواست‌های دیگر وسط render جواب می‌گیرند)، و بعد از ۳۰ و ۱۸۰ ثانیه با کل درخت processشان کشته می‌شوند: LibreOffice گیرکرده نمی‌تواند سرور را گیر بیندازد."],examples:["timer","kill"]},{id:"errors",h:"خطاها با status درست",p:["خطاهای شناخته‌شده به status خودشان می‌رسند (423 فایل قفل، 400 پوشه‌ی ناامن یا مقداری که دیتابیس رد کرده، 429 و 502 از Claude)؛ هر چیز دیگر 500 است که پیامش، که ممکن است مسیرهای سرور را داشته باشد، در production log می‌شود ولی فرستاده نمی‌شود."],examples:["errors"]}],examples:{name:{title:{en:"A safe folder name",fa:"اسم پوشه‌ی امن"},lang:"javascript",file:"server/src/paths.js",from:"const FOLDER_NAME_RE",lines:5},resolve:{title:{en:"Strictly inside applications/",fa:"دقیقاً داخل applications/"},lang:"javascript",file:"server/src/paths.js",from:"export function resolveApplicationFolder(applicationsDir, name) {",lines:9},atomic:{title:{en:"Temp file, then rename",fa:"فایل موقت، بعد rename"},lang:"javascript",file:"server/src/csv.js",from:"export function writeFileAtomic(file, content) {",lines:11},locked:{title:{en:"Open in Excel",fa:"در Excel باز است"},lang:"javascript",file:"server/src/csv.js",from:"export class FileLockedError extends Error {",lines:7},timer:{title:{en:"Past the timeout: kill",fa:"بعد از timeout: کشتن"},lang:"javascript",file:"server/src/process.js",from:"const timer = setTimeout(() => {",lines:4},kill:{title:{en:"The whole process tree",fa:"کل درخت process"},lang:"javascript",file:"server/src/process.js",from:"function killTree(pid, isWindows) {",lines:11},errors:{title:{en:"Known errors, known statuses",fa:"خطاهای شناخته، statusهای شناخته"},lang:"javascript",file:"server/src/app.js",from:"function sendError(res, err) {",lines:22}},quiz:[{q:{en:"Why is an application addressed by its folder name and not by its row position?",fa:"چرا یک درخواست با نام پوشه‌اش آدرس‌دهی می‌شود و نه با شماره‌ی ردیفش؟"},options:{en:["Row numbers are slower to look up","After another row is removed or added, a position can point at a different application","CSV files have no row numbers"],fa:["جست‌وجوی شماره‌ی ردیف کندتر است","بعد از حذف یا اضافه شدن ردیفی دیگر، یک شماره می‌تواند به درخواست دیگری اشاره کند","فایل CSV شماره‌ی ردیف ندارد"]},answer:1,why:{en:"A folder name is stable, so an edit or a delete always lands on the intended application.",fa:"نام پوشه ثابت است، پس ویرایش یا حذف همیشه روی همان درخواست موردنظر می‌نشیند."}},{q:{en:"What does the atomic write (temp file, then rename) guarantee if the server crashes mid-save?",fa:"نوشتن اتمی (فایل موقت، بعد rename) اگر سرور وسط ذخیره از کار بیفتد چه چیزی را تضمین می‌کند؟"},options:{en:["That `ledger.csv` is either the old file or the new one, never half of one","That the change is retried after restart","That Excel closes the file"],fa:["اینکه `ledger.csv` یا فایل قدیمی است یا فایل جدید، هرگز نیمی از یکی","اینکه تغییر بعد از راه‌اندازی دوباره تکرار می‌شود","اینکه Excel فایل را می‌بندد"]},answer:0,why:{en:"The rename is the only step that replaces the file, and it either happens or it does not.",fa:"rename تنها قدمی است که فایل را جایگزین می‌کند، و یا انجام می‌شود یا نمی‌شود."}},{q:{en:"Why are `validate.py` and `build.py` killed with their whole process tree after a timeout?",fa:"چرا `validate.py` و `build.py` بعد از timeout همراه کل درخت processشان کشته می‌شوند؟"},options:{en:["To free the build lock for the next day","Because Python cannot exit by itself","So a hung child such as LibreOffice cannot keep running and hang the server"],fa:["تا قفل build برای روز بعد آزاد شود","چون Python خودش نمی‌تواند خارج شود","تا یک فرزند گیرکرده مثل LibreOffice نتواند به اجرا ادامه دهد و سرور را معطل کند"]},answer:2,why:{en:"Killing only the parent would leave LibreOffice running; killing the tree stops everything the script started.",fa:"کشتن فقط والد LibreOffice را در حال اجرا رها می‌کرد؛ کشتن درخت هر چیزی را که اسکریپت راه انداخته متوقف می‌کند."}}]},{id:"applications",group:"ledger",title:{en:"Applications, by folder",fa:"درخواست‌ها، با پوشه"},files:["server/src/app.js","client/src/pages/ApplicationsList.jsx","client/src/pages/ApplicationDetail.jsx"],en:[{id:"endpoints",h:"Endpoints",p:["`:id` is the folder. A new application, typed in or analyzed, starts as a draft with its own folder named after the date, the company and the role.","Two applications for the same role at the same company on the same day would get the same name, so the server checks both the ledger and the disk and adds `-2`, `-3`... until the name is free. The name is resolved inside `applications/` before the folder is created, so the same safety rule applies here as everywhere else.","`POST /api/applications` can also carry the posting text, saved as `posting.txt`, which is how the nightly search saves postings without spending API credit. If it sends its own score and template too, they are kept in `analysis.json` marked `nightly-estimate`; a click on Analyze later replaces them with the engine's real score."],data:{kind:"endpoints",only:["applications"]},examples:["folder","unique","estimate"]},{id:"edit",h:"What may be edited",p:["`PATCH` changes the tracking fields only (notes, next action, last contact, outcome, gap tags, the hiring contact). The stage goes through pipeline events, and the posting's own facts come from how the package was built.","Any other key in the body is silently ignored, and a body with no editable field at all answers 400, so a typo can not pass as a successful save. Contact fields are checked together (see the contact topic), and a gap tag typed by hand that was merged into another gap is mapped to the gap it now counts as."],examples:["editable"]},{id:"delete",h:"Deleting a draft",p:["Deleting removes the row and its folder: it is meant for a draft you skipped, not as an archive. It is refused while a build is running for that folder.","What happens to the pipeline events is up to the store: the CSV store leaves them in the append-only file, where nothing looks them up any more, and the SQL store deletes them with the row."],examples:["delete"]},{id:"files",h:"Files, only by their listed name",p:["Builds run on the server, so a package reaches the PC as a download. Only names that actually appear in the folder's listing are served, so no path can be slipped in."],examples:["download"]}],fa:[{id:"endpoints",h:"endpointها",p:["`:id` همان پوشه است. درخواست تازه، چه تایپ‌شده چه analyze‌شده، به‌صورت پیش‌نویس شروع می‌شود با پوشه‌ی خودش به اسم تاریخ، شرکت و نقش.","دو درخواست برای همان نقش در همان شرکت در همان روز نام یکسانی می‌گرفتند، پس سرور هم ledger و هم دیسک را بررسی می‌کند و `-2`، `-3`... اضافه می‌کند تا نام آزاد شود. نام پیش از ساخته شدن پوشه داخل `applications/` resolve می‌شود، پس همان قاعده‌ی ایمنی همه‌جا اینجا هم برقرار است.","`POST /api/applications` می‌تواند متن آگهی را هم بیاورد که به‌صورت `posting.txt` ذخیره می‌شود؛ جست‌وجوی شبانه آگهی‌ها را همین‌طور بدون خرج اعتبار API ذخیره می‌کند. اگر امتیاز و قالب خودش را هم بفرستد، در `analysis.json` با برچسب `nightly-estimate` نگه داشته می‌شوند؛ یک کلیک روی Analyze بعداً آن‌ها را با امتیاز واقعی engine عوض می‌کند."],data:{kind:"endpoints",only:["applications"]},examples:["folder","unique","estimate"]},{id:"edit",h:"چه چیزی ویرایش می‌شود",p:["`PATCH` فقط فیلدهای پیگیری را عوض می‌کند (یادداشت، قدم بعدی، آخرین تماس، نتیجه، gap tagها، مخاطب استخدام). مرحله از رویدادهای pipeline عوض می‌شود، و مشخصات خود آگهی از نحوه‌ی ساخته شدن بسته می‌آیند.","هر کلید دیگری در body بی‌صدا نادیده گرفته می‌شود، و bodyای که هیچ فیلد قابل‌ویرایشی ندارد 400 می‌گیرد، تا یک غلط تایپی به‌جای ذخیره‌ی موفق جا نخورد. فیلدهای contact با هم بررسی می‌شوند (topic مربوط به contact)، و gap tagی که دستی تایپ شده و در gap دیگری ادغام شده، به همان gapی نگاشت می‌شود که حالا حساب می‌شود."],examples:["editable"]},{id:"delete",h:"حذف یک پیش‌نویس",p:["حذف ردیف و پوشه‌اش را پاک می‌کند: برای پیش‌نویسی است که ردش کرده‌ای، نه برای بایگانی. وقتی برای آن پوشه build در جریان است رد می‌شود.","اینکه eventهای pipeline چه شوند به store بستگی دارد: store مربوط به CSV آن‌ها را در فایل فقط‌افزودنی رها می‌کند، جایی که دیگر چیزی سراغشان نمی‌رود، و store مربوط به SQL آن‌ها را همراه ردیف حذف می‌کند."],examples:["delete"]},{id:"files",h:"فایل‌ها، فقط با اسمی که در فهرست هست",p:["buildها روی سرور اجرا می‌شوند، پس بسته به‌صورت دانلود به PC می‌رسد. فقط اسم‌هایی سرو می‌شوند که واقعاً در فهرست پوشه هستند، پس هیچ مسیری نمی‌شود جا زد."],examples:["download"]}],examples:{folder:{title:{en:"A folder name that doesn't collide",fa:"اسم پوشه‌ای که تکراری نمی‌شود"},lang:"javascript",file:"server/src/app.js",from:"const base = `${date}__${slugify(company)",lines:7},editable:{title:{en:"The editable fields",fa:"فیلدهای قابل ویرایش"},lang:"javascript",file:"server/src/app.js",from:"const EDITABLE_LEDGER_FIELDS = new Set([",lines:3},delete:{title:{en:"Not while it's building",fa:"نه وقتی در حال build است"},lang:"javascript",file:"server/src/app.js",from:'app.delete("/api/applications/:id"',lines:18},download:{title:{en:"Only listed names",fa:"فقط اسم‌های فهرست‌شده"},lang:"javascript",file:"server/src/app.js",from:"const listed = existsSync(folderPath) ? readdirSync(folderPath) : [];",lines:3},unique:{title:{en:"Same day, same role: a numbered folder",fa:"همان روز، همان نقش: پوشه‌ی شماره‌دار"},lang:"javascript",file:"server/src/app.js",from:"const existingFolders = new Set(rows.map((r) => r.folder));",lines:6},estimate:{title:{en:"A nightly estimate, marked as one",fa:"برآورد شبانه، با برچسب برآورد"},lang:"javascript",file:"server/src/app.js",from:"if (variant && postingText) {",lines:13}},quiz:[{q:{en:"Why can a `PATCH` not move an application to another stage?",fa:"چرا یک `PATCH` نمی‌تواند درخواست را به مرحله‌ی دیگری ببرد؟"},options:{en:["Because stages are only changed in Excel","Because the stage is a history of pipeline events, and overwriting a field would lose that history","Because the stage is computed by Claude"],fa:["چون مرحله فقط در Excel عوض می‌شود","چون مرحله تاریخچه‌ای از eventهای pipeline است و بازنویسی یک فیلد آن تاریخچه را از بین می‌برد","چون مرحله را Claude محاسبه می‌کند"]},answer:1,why:{en:"The editable set holds tracking fields only; a stage change is appended as an event so nothing is lost.",fa:"مجموعه‌ی قابل‌ویرایش فقط فیلدهای پیگیری را دارد؛ تغییر مرحله به‌صورت یک event اضافه می‌شود تا چیزی از دست نرود."}},{q:{en:"What happens if you try to delete a draft while its package is being built?",fa:"اگر بخواهید draftی را در حالی که بسته‌اش در حال build است حذف کنید چه می‌شود؟"},options:{en:["The delete is refused with 409","The build is cancelled and the folder removed","The row is removed but the folder stays"],fa:["حذف با 409 رد می‌شود","build لغو و پوشه حذف می‌شود","ردیف حذف می‌شود ولی پوشه می‌ماند"]},answer:0,why:{en:"The build is writing files into that folder; deleting it underneath would race with the render.",fa:"build در حال نوشتن فایل در همان پوشه است؛ حذفش از زیر پای آن با render مسابقه می‌داد."}},{q:{en:"A download asks for `../ledger.csv` as the file name. What stops it?",fa:"یک دانلود نام فایل را `../ledger.csv` می‌خواهد. چه چیزی جلویش را می‌گیرد؟"},options:{en:["The browser strips `..` from URLs","Express rejects any name with a dot","Only names that appear in the folder's own listing are served, so it gets 404"],fa:["مرورگر `..` را از URL حذف می‌کند","Express هر نامی را که نقطه دارد رد می‌کند","فقط نام‌هایی که در فهرست خود پوشه هستند سرو می‌شوند، پس 404 می‌گیرد"]},answer:2,why:{en:"The name is compared against `readdirSync` of the folder, so a path can never be slipped in.",fa:"نام با `readdirSync` همان پوشه مقایسه می‌شود، پس هیچ مسیری نمی‌تواند لای آن جا بخورد."}}]},{id:"pipeline",group:"ledger",title:{en:"The pipeline: append-only stages, follow-ups",fa:"pipeline: مرحله‌های فقط‌افزودنی، پیگیری‌ها"},files:["server/src/pipeline.js","server/src/stores/csvStore.js","server/src/stores/sqlStore.js","client/src/pages/PipelineBoard.jsx"],en:[{id:"endpoints",h:"Endpoints",p:["Dragging a card on the Pipeline board (Draft → … → Contract signed) adds an event; nothing is overwritten."],data:{kind:"endpoints",only:["pipeline-events","pipeline-stages"]}},{id:"events",h:"The last event is the stage",p:["Stage changes are events appended to `pipeline.csv` (or `PipelineEvents`), and an application's current stage is its last stage-changing event: the history is never lost. A follow-up is an event too, but it doesn't change the stage."],examples:["append","current"]},{id:"followup",h:"Seven silent days",p:["Stages marked `waiting` in `pipeline_stages.yml` mean the employer has to act next. After 7 days without action (entering the stage, or the last follow-up, whichever is newer) the card asks for a follow-up; logging one restarts the clock."],examples:["since"]},{id:"dates",h:"Dates in local time",p:['`new Date("2026-09-10")` would be UTC midnight, the previous evening in Toronto, and "days in stage" would be off by one depending on the hour. Ledger dates are read as local calendar dates, and a future date (a booked interview) counts down instead of becoming zero.'],examples:["local"]},{id:"undo",h:"Undo, but never the draft",p:["A stage marked by mistake can be taken back: the latest event, or every event after the first. The first event, the row's own draft, always stays."],examples:["undo"]}],fa:[{id:"endpoints",h:"endpointها",p:["کشیدن یک کارت روی صفحه‌ی Pipeline (Draft → … → Contract signed) یک رویداد اضافه می‌کند؛ هیچ چیز رونویسی نمی‌شود."],data:{kind:"endpoints",only:["pipeline-events","pipeline-stages"]}},{id:"events",h:"آخرین رویداد همان مرحله است",p:["تغییر مرحله‌ها رویدادهایی‌اند که به `pipeline.csv` (یا `PipelineEvents`) اضافه می‌شوند، و مرحله‌ی فعلی یک درخواست آخرین رویداد تغییر مرحله‌ی آن است: تاریخچه هیچ‌وقت گم نمی‌شود. پیگیری هم یک رویداد است، ولی مرحله را عوض نمی‌کند."],examples:["append","current"]},{id:"followup",h:"هفت روز سکوت",p:["مرحله‌هایی که در `pipeline_stages.yml` با `waiting` علامت خورده‌اند یعنی قدم بعدی با کارفرماست. بعد از ۷ روز بی‌کاری (ورود به مرحله، یا آخرین پیگیری، هر کدام تازه‌تر) کارت پیگیری می‌خواهد؛ ثبت یک پیگیری ساعت را از نو شروع می‌کند."],examples:["since"]},{id:"dates",h:"تاریخ‌ها به وقت محلی",p:['`new Date("2026-09-10")` نیمه‌شب UTC می‌شد، که در Toronto عصر روز قبل است، و «روزهای این مرحله» بسته به ساعت یکی جابه‌جا می‌شد. تاریخ‌های ledger به‌صورت تاریخ تقویم محلی خوانده می‌شوند، و تاریخ آینده (یک مصاحبه‌ی رزروشده) شمارش معکوس می‌شود نه صفر.'],examples:["local"]},{id:"undo",h:"برگرداندن، ولی هیچ‌وقت پیش‌نویس",p:["مرحله‌ای که اشتباهی زده شده را می‌شود پس گرفت: آخرین رویداد، یا همه‌ی رویدادهای بعد از اولی. رویداد اول، یعنی پیش‌نویس خود ردیف، همیشه می‌ماند."],examples:["undo"]}],examples:{append:{title:{en:"One more line in pipeline.csv",fa:"یک خط دیگر در pipeline.csv"},lang:"javascript",file:"server/src/stores/csvStore.js",from:"function appendEventLine({ folder, company, stage, date, note }) {",lines:7},current:{title:{en:"The current stage",fa:"مرحله‌ی فعلی"},lang:"javascript",file:"server/src/pipeline.js",from:"const stageEvents = history.filter((h) => h.stage !== FOLLOWUP_KEY);",lines:3},since:{title:{en:"When a follow-up is due",fa:"پیگیری کی لازم است"},lang:"javascript",file:"server/src/pipeline.js",from:"const lastActionDate =",lines:10},local:{title:{en:"A ledger date as a local date",fa:"تاریخ ledger به‌صورت تاریخ محلی"},lang:"javascript",file:"server/src/pipeline.js",from:"export function parseLocalDate(value) {",lines:7},undo:{title:{en:"Undo in one DELETE",fa:"برگرداندن در یک DELETE"},lang:"javascript",file:"server/src/stores/sqlStore.js",from:"async removeEvents(folder, { all = false } = {}) {",lines:15}},quiz:[{q:{en:"How is an application's current stage found?",fa:"مرحله‌ی فعلی یک درخواست چطور پیدا می‌شود؟"},options:{en:["From a `stage` column that is overwritten on every move","From the last stage-changing event in its history","From the most recent follow-up"],fa:["از ستون `stage` که با هر جابه‌جایی بازنویسی می‌شود","از آخرین event تغییردهنده‌ی مرحله در تاریخچه‌اش","از تازه‌ترین follow-up"]},answer:1,why:{en:"Events are only appended; follow-ups are events too but are filtered out because they do not change the stage.",fa:"eventها فقط اضافه می‌شوند؛ follow-up هم event است ولی کنار گذاشته می‌شود چون مرحله را عوض نمی‌کند."}},{q:{en:'Why are ledger dates parsed as local calendar dates instead of with `new Date("2026-09-10")`?',fa:'چرا تاریخ‌های ledger به‌صورت تاریخ تقویمی محلی خوانده می‌شوند و نه با `new Date("2026-09-10")`؟'},options:{en:["Because that form is UTC midnight, the previous evening in Toronto, so day counts would be off by one","Because `new Date` can not parse dashes","Because SQL Server stores dates as text"],fa:["چون آن شکل نیمه‌شب UTC است، یعنی عصر روز قبل در Toronto، و شمارش روزها یکی جابه‌جا می‌شد","چون `new Date` نمی‌تواند خط تیره را بخواند","چون SQL Server تاریخ را متنی ذخیره می‌کند"]},answer:0,why:{en:'Reading the date as a local date keeps "days in stage" the same whatever the hour.',fa:"خواندن تاریخ به‌صورت محلی، «روزهای ماندن در مرحله» را در هر ساعتی یکسان نگه می‌دارد."}},{q:{en:"When you log a follow-up on a waiting card, what happens to the 7-day clock?",fa:"وقتی برای کارتی در حالت انتظار follow-up ثبت می‌کنید، ساعت ۷ روزه چه می‌شود؟"},options:{en:["Nothing, it counts from entering the stage","The card moves to the next stage","It restarts, because the newer of the stage entry and the last follow-up is used"],fa:["هیچ، از ورود به مرحله شمرده می‌شود","کارت به مرحله‌ی بعد می‌رود","از نو شروع می‌شود، چون تازه‌ترینِ ورود به مرحله و آخرین follow-up به کار می‌رود"]},answer:2,why:{en:"The last action date is whichever is newer, so a follow-up resets the count without changing the stage.",fa:"تاریخ آخرین اقدام هر کدام تازه‌تر باشد است، پس follow-up شمارش را بدون تغییر مرحله صفر می‌کند."}}]},{id:"contact",group:"ledger",title:{en:"The hiring contact: published or verified only",fa:"مخاطب استخدام: فقط منتشرشده یا تأییدشده"},files:["server/src/contact.js","db/03-schema.sql","client/src/components/ContactEditor.jsx","client/src/contact.js"],en:[{id:"rule",h:"No guessed addresses",p:["Marking an application as sent first asks who it went to and where their email came from. A guessed `careers@` or `firstname@` usually bounces or goes unread, which is worse than not writing, so only an address the posting showed, the ATS confirmation replied from or the person wrote from is stored. One you found yourself must be marked as checked.","`resolveContact` merges the change into the row's current contact and returns the four fields to store. With no email, the name is kept and the source and the checked mark are cleared, since there is nothing left to vouch for. With an email, it is trimmed and lower-cased, must look like an address, must name one of the four sources, and must be either published by its source or marked as checked. Anything else throws a `ContactValidationError`, which the server answers as 400 with the reason, so the form shows why the address was not saved."],examples:["sources","resolve"]},{id:"twice",h:"Refused twice",p:["The API applies the rule to the merged contact (a change to one field is checked with the others), and SQL Server refuses a row that breaks it with a CHECK constraint, so a script or a hand-written UPDATE can't store one either."],examples:["patch","check"]},{id:"email",h:"The follow-up email",p:["After 7 silent days, *Email follow-up* opens a short draft in your own mail app; nothing is sent from the dashboard. Confirming it logs the follow-up and restarts the clock.","The draft is a `mailto:` link built in the browser: the subject names the role, the body greets the contact by first name and says when you applied, taken from the latest `applied` event. Every part is URL-encoded, and your mail app is where you adjust and send it, so the dashboard never needs mail credentials."],examples:["mailto"]}],fa:[{id:"rule",h:"هیچ آدرس حدسی",p:["علامت زدن یک درخواست به‌عنوان فرستاده‌شده اول می‌پرسد به چه کسی رفته و ایمیلش از کجا آمده. یک `careers@` یا `firstname@` حدسی معمولاً برمی‌گردد یا خوانده نمی‌شود، که از ننوشتن بدتر است، پس فقط آدرسی ذخیره می‌شود که آگهی نشان داده، تأیید ATS از آن جواب داده یا خود آن آدم از آن نوشته. آدرسی که خودت پیدا کرده‌ای باید علامت چک‌شده بخورد.","`resolveContact` تغییر را با contact فعلی ردیف ادغام می‌کند و چهار فیلدی را که باید ذخیره شوند برمی‌گرداند. بدون ایمیل، نام نگه داشته می‌شود و منبع و علامت بررسی‌شده پاک می‌شوند، چون دیگر چیزی برای ضمانت نمانده. با ایمیل، فاصله‌ها حذف و حروف کوچک می‌شود، باید شبیه یک آدرس باشد، باید یکی از چهار منبع را نام ببرد، و باید یا منبعش آن را منتشر کرده باشد یا علامت بررسی‌شده بخورد. هر حالت دیگری یک `ContactValidationError` می‌اندازد که سرور با 400 و دلیلش پاسخ می‌دهد، تا فرم نشان دهد چرا آدرس ذخیره نشد."],examples:["sources","resolve"]},{id:"twice",h:"دو بار رد می‌شود",p:["API قانون را روی مخاطب ادغام‌شده اعمال می‌کند (تغییر یک فیلد با بقیه چک می‌شود)، و SQL Server ردیفی را که آن را بشکند با یک CHECK constraint رد می‌کند، پس اسکریپت یا یک UPDATE دست‌نویس هم نمی‌تواند چنین چیزی ذخیره کند."],examples:["patch","check"]},{id:"email",h:"ایمیل پیگیری",p:["بعد از ۷ روز سکوت، *Email follow-up* یک پیش‌نویس کوتاه در اپ ایمیل خودت باز می‌کند؛ هیچ چیز از داشبورد فرستاده نمی‌شود. تأییدش پیگیری را ثبت و ساعت را از نو شروع می‌کند.","پیش‌نویس یک لینک `mailto:` است که در مرورگر ساخته می‌شود: موضوع نام نقش را دارد، متن با نام کوچک contact سلام می‌کند و می‌گوید کی درخواست داده‌اید، که از آخرین event `applied` گرفته می‌شود. همه‌ی بخش‌ها URL-encode می‌شوند، و برنامه‌ی ایمیل خودتان جایی است که آن را ویرایش و ارسال می‌کنید، پس داشبورد هیچ‌وقت به اطلاعات ورود ایمیل نیاز ندارد."],examples:["mailto"]}],examples:{sources:{title:{en:"Where an address may come from",fa:"آدرس از کجا می‌تواند بیاید"},lang:"javascript",file:"server/src/contact.js",from:"export const CONTACT_SOURCES = {",lines:6},resolve:{title:{en:"Published, or marked verified",fa:"منتشرشده، یا علامت تأیید"},lang:"javascript",file:"server/src/contact.js",from:"const verified = CONTACT_SOURCES[source].published || isTrue(merged.contact_verified);",lines:7},patch:{title:{en:"Checked as a whole",fa:"به‌صورت یک کل چک می‌شود"},lang:"javascript",file:"server/src/app.js",from:"if (CONTACT_FIELDS.some((f) => f in updates)) {",lines:3},check:{title:{en:"The same rule in the database",fa:"همان قانون در دیتابیس"},lang:"sql",file:"db/03-schema.sql",from:"ALTER TABLE dbo.Applications ADD CONSTRAINT CK_Applications_Contact CHECK (",lines:5},mailto:{title:{en:"A draft in your own mail app",fa:"یک پیش‌نویس در برنامه‌ی ایمیل خودتان"},lang:"javascript",file:"client/src/contact.js",from:"export function followupMailto(app) {",to:"return `mailto:"}},quiz:[{q:{en:"Why does the server refuse a guessed address such as `careers@company.com`?",fa:"چرا سرور آدرس حدسی مثل `careers@company.com` را رد می‌کند؟"},options:{en:["Because a guessed address usually bounces or goes unread, which is worse than not writing","Because it is too long","Because only LinkedIn messages are allowed"],fa:["چون آدرس حدسی معمولاً برمی‌گردد یا خوانده نمی‌شود، که از ننوشتن بدتر است","چون خیلی طولانی است","چون فقط پیام LinkedIn مجاز است"]},answer:0,why:{en:"Only an address published by the posting, the ATS or the person, or one you checked yourself, is stored.",fa:"فقط آدرسی ذخیره می‌شود که آگهی، ATS یا خود شخص منتشر کرده، یا خودتان بررسی‌اش کرده‌اید."}},{q:{en:"You change only the email of a contact whose source is `found` and not checked. What happens?",fa:"فقط ایمیل contactی را عوض می‌کنید که منبعش `found` است و بررسی نشده. چه می‌شود؟"},options:{en:["It is saved, since only the email changed","It is refused, because the rule is applied to the merged contact, not to the changed field alone","The source is switched to `posting` automatically"],fa:["ذخیره می‌شود، چون فقط ایمیل عوض شده","رد می‌شود، چون قاعده روی contact ادغام‌شده اعمال می‌شود، نه فقط روی فیلد تغییرکرده","منبع خودکار به `posting` عوض می‌شود"]},answer:1,why:{en:"The update is merged with the stored fields first, so a self-found address still needs the checked mark.",fa:"به‌روزرسانی اول با فیلدهای ذخیره‌شده ادغام می‌شود، پس آدرسی که خودتان پیدا کرده‌اید هنوز علامت بررسی‌شده می‌خواهد."}},{q:{en:"Why is the same rule also a CHECK constraint in SQL Server?",fa:"چرا همان قاعده در SQL Server هم به‌صورت CHECK constraint آمده؟"},options:{en:["To make inserts faster","Because the API does not check contacts","So a script or a hand-written UPDATE that bypasses the API still can not store a bad contact"],fa:["تا insertها سریع‌تر شوند","چون API contactها را بررسی نمی‌کند","تا اسکریپت یا UPDATE دستی‌ای که API را دور می‌زند هم نتواند contact بد ذخیره کند"]},answer:2,why:{en:"The API gives a clear message; the database is the last line for anything that does not go through the API.",fa:"API پیام روشن می‌دهد؛ پایگاه داده آخرین خط دفاع برای هر چیزی است که از API نمی‌گذرد."}}]},{id:"boards",group:"ledger",title:{en:"Funnel, rejections, recruiters, evaluation",fa:"قیف، ردشده‌ها، recruiterها، ارزیابی"},files:["server/src/funnel.js","server/src/rejections.js","server/src/recruiterNext.js","server/src/evaluation.js"],en:[{id:"endpoints",h:"Endpoints",p:["The other pages read the same ledger and compute in plain functions, with no model call."],data:{kind:"endpoints",only:["funnel","rejections","recruiters","eval","motivation","gap-tags"]}},{id:"funnel",h:"The funnel and a forecast",p:["Applied → any reply → interview → offer, plus a 6-month forecast of an offer. Before there is much data of your own it starts from published rates as Beta priors with a weak weight, so a few weeks of real results move it quickly; a posting silent for 21 days counts as a no.","The forecast looks 26 weeks ahead but only counts applications sent in the first 20 of them, because hiring takes about four to six weeks: an application sent in week 25 can not turn into a job inside the horizon. A card dragged straight from Draft to Rejected or No response still counts as sent, dated by that event."],examples:["prior","horizon"]},{id:"rejections",h:"What the nightly run turned down",p:['The Rejections page reads the nightly job search\'s own daily reports (`engine/daily/YYYY-MM-DD.md`). They are written for a person, in Persian, so the parser trusts only their stable shape: a heading that says the rows below were rejected, then a markdown table with a company and a role column. "رد" has to be a whole word, because the same letters sit inside "فردا" (tomorrow) and "کرد"; and a "برای فردا" section lists postings that passed, so it is never read as rejects even if its heading mentions a rejection.',"The same company and role seen on several nights is one posting, shown with its latest reason. Marking it reviewed stores the date it was last seen, so if the run turns it down again later it shows up as new."],examples:["rejectWord"]},{id:"recruiters",h:"Recruiters at LinkedIn's pace",p:["The outreach list says what to do next with each person (connect, wait, first message, follow up, monthly check-in), from the dates already stored. Connects go out without a note, and the daily and weekly targets warn before LinkedIn's limits would."],examples:["caps"]},{id:"eval",h:"Is the score any good?",p:["Each saved posting can be labelled apply or skip without seeing the model's score, so the label isn't anchored on it. The labels against the scores give a confusion matrix, accuracy, precision and recall at a chosen threshold."],examples:["confusion"]}],fa:[{id:"endpoints",h:"endpointها",p:["صفحه‌های دیگر همان ledger را می‌خوانند و با تابع‌های ساده حساب می‌کنند، بدون صدا زدن مدل."],data:{kind:"endpoints",only:["funnel","rejections","recruiters","eval","motivation","gap-tags"]}},{id:"funnel",h:"قیف و یک پیش‌بینی",p:["فرستاده → هر جوابی → مصاحبه → پیشنهاد، به‌علاوه‌ی پیش‌بینی ۶ ماهه‌ی یک پیشنهاد کار. پیش از این‌که داده‌ی خودت زیاد شود از نرخ‌های منتشرشده به‌صورت prior بتا با وزن کم شروع می‌کند، پس چند هفته نتیجه‌ی واقعی سریع جابه‌جایش می‌کند؛ آگهی‌ای که ۲۱ روز ساکت مانده «نه» حساب می‌شود.","پیش‌بینی ۲۶ هفته جلو را می‌بیند ولی فقط درخواست‌هایی را می‌شمارد که در ۲۰ هفته‌ی اول فرستاده شده‌اند، چون استخدام حدود چهار تا شش هفته طول می‌کشد: درخواستی که در هفته‌ی ۲۵ فرستاده شود نمی‌تواند داخل این بازه به کار برسد. کارتی که مستقیم از Draft به Rejected یا No response کشیده شده هم فرستاده‌شده حساب می‌شود، با تاریخ همان event."],examples:["prior","horizon"]},{id:"rejections",h:"آنچه اجرای شبانه رد کرد",p:["صفحه‌ی Rejections گزارش‌های روزانه‌ی خود جست‌وجوی شبانه را می‌خواند (`engine/daily/YYYY-MM-DD.md`). این گزارش‌ها برای آدم و به فارسی نوشته شده‌اند، پس parser فقط به شکل ثابتشان اعتماد می‌کند: عنوانی که می‌گوید ردیف‌های زیرش رد شده‌اند، و بعد یک جدول markdown با ستون شرکت و ستون نقش. «رد» باید کلمه‌ی کامل باشد، چون همین حروف داخل «فردا» و «کرد» هم هست؛ و بخش «برای فردا» آگهی‌هایی را فهرست می‌کند که قبول شده‌اند، پس حتی اگر عنوانش به ردی اشاره کند هرگز رد خوانده نمی‌شود.","همان شرکت و نقش که در چند شب دیده شده یک آگهی است و با تازه‌ترین دلیلش نشان داده می‌شود. علامت «بررسی شد» تاریخ آخرین دیده شدن را نگه می‌دارد، پس اگر اجرا بعداً دوباره ردش کند، دوباره به‌عنوان مورد تازه دیده می‌شود."],examples:["rejectWord"]},{id:"recruiters",h:"recruiterها با سرعت لینکدین",p:["فهرست ارتباط‌گیری می‌گوید با هر نفر قدم بعدی چیست (دعوت، صبر، پیام اول، پیگیری، سر زدن ماهانه)، از روی تاریخ‌هایی که از قبل ذخیره شده‌اند. دعوت‌ها بدون یادداشت می‌روند، و هدف‌های روزانه و هفتگی قبل از محدودیت‌های لینکدین هشدار می‌دهند."],examples:["caps"]},{id:"eval",h:"امتیاز به درد می‌خورد؟",p:["هر آگهی ذخیره‌شده را می‌شود بدون دیدن امتیاز مدل با apply یا skip برچسب زد، تا برچسب به آن لنگر نیندازد. برچسب‌ها در برابر امتیازها یک confusion matrix، accuracy، precision و recall در آستانه‌ی انتخابی می‌دهند."],examples:["confusion"]}],examples:{prior:{title:{en:"Priors before your own data",fa:"priorها پیش از داده‌ی خودت"},lang:"javascript",file:"server/src/funnel.js",from:"// Benchmarks before any of the user's own data",lines:6},caps:{title:{en:"LinkedIn's pace",fa:"سرعت لینکدین"},lang:"javascript",file:"server/src/recruiterNext.js",from:"// LinkedIn (free) allows only a few personalised invites",lines:9},confusion:{title:{en:"Score against label",fa:"امتیاز در برابر برچسب"},lang:"javascript",file:"server/src/evaluation.js",from:"export function confusion(items, threshold) {",lines:22},horizon:{title:{en:"Only applications that can still become a job",fa:"فقط درخواست‌هایی که هنوز می‌توانند کار شوند"},lang:"javascript",file:"server/src/funnel.js",from:"// Hiring takes ~4-6 weeks",lines:4},rejectWord:{title:{en:'"رد" as a whole word only',fa:"«رد» فقط به‌صورت کلمه‌ی کامل"},lang:"javascript",file:"server/src/rejections.js",from:'// "برای فردا" sections list postings',to:"const REJECT_WORD_RE"}},quiz:[{q:{en:"Why does the funnel forecast start from published rates as weak Beta priors?",fa:"چرا پیش‌بینی funnel از نرخ‌های منتشرشده به‌صورت Beta priorهای ضعیف شروع می‌کند؟"},options:{en:["So it gives a sensible estimate before there is much data of your own, and a few weeks of real results move it quickly","Because your own data is never used","Because Claude computes the forecast"],fa:["تا پیش از اینکه داده‌ی زیادی از خودتان باشد برآورد معقولی بدهد و چند هفته نتیجه‌ی واقعی سریع جابه‌جایش کند","چون داده‌ی خودتان هرگز استفاده نمی‌شود","چون Claude پیش‌بینی را حساب می‌کند"]},answer:0,why:{en:"A weak weight means the prior matters only until real outcomes outnumber it.",fa:"وزن ضعیف یعنی prior فقط تا وقتی اهمیت دارد که نتیجه‌های واقعی از آن بیشتر شوند."}},{q:{en:'Why must "رد" match as a whole word when reading the nightly reports?',fa:"چرا هنگام خواندن گزارش‌های شبانه «رد» باید به‌صورت کلمه‌ی کامل تطبیق داده شود؟"},options:{en:["Because headings are in English",'Because the same letters appear inside other words such as "فردا", which would turn waiting postings into rejects',"Because markdown tables can not contain Persian"],fa:["چون عنوان‌ها انگلیسی‌اند","چون همین حروف داخل کلمه‌های دیگری مثل «فردا» هم هست و آگهی‌های در انتظار را رد شده نشان می‌داد","چون جدول markdown نمی‌تواند فارسی داشته باشد"]},answer:1,why:{en:'A substring match would read a "for tomorrow" section as rejections.',fa:"تطبیق زیررشته‌ای بخش «برای فردا» را به‌عنوان ردشده‌ها می‌خواند."}},{q:{en:"Why is each posting labelled apply or skip without seeing the model's score?",fa:"چرا هر آگهی بدون دیدن امتیاز مدل با apply یا skip برچسب می‌خورد؟"},options:{en:["To save tokens","Because the score is not stored","So the label is not anchored on the score, and the confusion matrix measures the score honestly"],fa:["برای صرفه‌جویی در token","چون امتیاز ذخیره نمی‌شود","تا برچسب به امتیاز لنگر نیندازد و confusion matrix امتیاز را صادقانه بسنجد"]},answer:2,why:{en:"A label made while looking at the score would tend to agree with it, which would make the score look better than it is.",fa:"برچسبی که با دیدن امتیاز زده شود به موافقت با آن متمایل است و امتیاز را بهتر از واقع نشان می‌دهد."}}]},{id:"analyze",group:"ai",title:{en:"Analyze: a cheap first call",fa:"Analyze: یک صدا زدن ارزان اول"},files:["server/src/app.js","client/src/pages/NewPackage.jsx"],en:[{id:"endpoints",h:"Two stages, with you in between",p:["Pasting a posting calls `/api/packages/analyze`: Claude scores it against the fact bank, lists the gaps and picks a résumé template, and a draft is created. Only after you choose Apply does `/api/packages/build` make the heavy call, so a posting you skip costs only the analysis."],data:{kind:"endpoints",only:["packages"]}},{id:"strict",h:"A strict tool, then checks anyway",p:["The answer is a forced call to a `strict` tool, so its input matches the schema (without it the model sometimes dropped the gap tags or nested them in the wrong field). A cut-off answer, or gaps listed without gap tags, still throws, and nothing is saved."],examples:["strict","normalize"]},{id:"closed",h:"Closed gaps, enforced here",p:["The prompt tells the model never to use a gap the fact bank has closed, and it has done so anyway, so the gap dictionary is enforced on the server: closed slugs are dropped (and listed) whoever scored the posting, after merged slugs are mapped to the gap they now count as."],examples:["closed"]},{id:"cache",h:"The fact bank, cached",p:["The fact bank is about 35k tokens and the same in every call, so the system prompt is marked for prompt caching: another analysis within a few minutes reads it at about a tenth of the price. A draft can be re-analyzed against today's fact bank, but only while it is still a draft: once sent, its gap tags record what was missing when it went out."],examples:["cached","draftOnly"]}],fa:[{id:"endpoints",h:"دو مرحله، و تو وسطشان",p:["چسباندن یک آگهی `/api/packages/analyze` را صدا می‌زند: Claude آن را در برابر fact bank امتیاز می‌دهد، gapها را فهرست می‌کند و یک قالب رزومه انتخاب می‌کند، و یک پیش‌نویس ساخته می‌شود. فقط بعد از این‌که Apply را انتخاب کنی `/api/packages/build` صدا زدن سنگین را انجام می‌دهد، پس آگهی‌ای که ردش کنی فقط هزینه‌ی analysis را دارد."],data:{kind:"endpoints",only:["packages"]}},{id:"strict",h:"یک tool سخت‌گیر، و باز هم چک",p:["جواب یک صدا زدن اجباری به یک tool از نوع `strict` است، پس ورودی‌اش با schema جور است (بدون آن مدل گاهی gap tagها را جا می‌انداخت یا در فیلد غلط می‌گذاشت). جواب بریده، یا gapهایی که بدون gap tag آمده‌اند، باز هم خطا می‌اندازند، و هیچ چیز ذخیره نمی‌شود."],examples:["strict","normalize"]},{id:"closed",h:"gapهای بسته، این‌جا اجبار می‌شوند",p:["prompt به مدل می‌گوید هیچ‌وقت gapی را که fact bank بسته به کار نبرد، و مدل با این حال این کار را کرده، پس دیکشنری gap روی سرور اجبار می‌شود: slugهای بسته حذف می‌شوند (و فهرست می‌شوند)، هر کس امتیاز داده باشد، بعد از این‌که slugهای ادغام‌شده به gapی که حالا حساب می‌شوند برگردانده شدند."],examples:["closed"]},{id:"cache",h:"fact bank، cache‌شده",p:["fact bank حدود ۳۵ هزار token است و در هر صدا زدن همان است، پس system prompt برای prompt caching علامت خورده: analysis دیگری در چند دقیقه آن را با حدود یک‌دهم قیمت می‌خواند. پیش‌نویس را می‌شود در برابر fact bank امروز دوباره analyze کرد، ولی فقط تا وقتی پیش‌نویس است: بعد از فرستادن، gap tagهایش ثبت می‌کنند وقتی فرستاده شد چه چیزی کم بود."],examples:["cached","draftOnly"]}],examples:{strict:{title:{en:"Why strict",fa:"چرا strict"},lang:"javascript",file:"server/src/app.js",from:"// strict: the API then guarantees the input matches this schema.",lines:9},normalize:{title:{en:"Fail loudly, save nothing",fa:"با صدای بلند شکست بخور، هیچ چیز ذخیره نکن"},lang:"javascript",file:"server/src/app.js",from:'if (message.stop_reason === "max_tokens") {',lines:11},closed:{title:{en:"Dropping closed gaps",fa:"حذف gapهای بسته"},lang:"javascript",file:"server/src/app.js",from:"function withoutClosedGaps(rawTags) {",lines:6},cached:{title:{en:"The cache breakpoint",fa:"نقطه‌ی cache"},lang:"javascript",file:"server/src/app.js",from:'function cachedSystem(text, tail = "") {',lines:5},draftOnly:{title:{en:"Drafts only",fa:"فقط پیش‌نویس"},lang:"javascript",file:"server/src/app.js",from:'if (row.stage !== "draft") {',lines:3}},quiz:[{q:{en:"Why is the analysis split from the build, with you choosing Apply in between?",fa:"چرا تحلیل از build جدا شده و شما در میانه Apply را انتخاب می‌کنید؟"},options:{en:["So a posting you skip costs only the cheap analysis, not the heavy build call","Because the API can not do both in one request","So the build can run overnight"],fa:["تا آگهی‌ای که رد می‌کنید فقط هزینه‌ی تحلیل ارزان را داشته باشد، نه فراخوانی سنگین build را","چون API نمی‌تواند هر دو را در یک درخواست انجام دهد","تا build شبانه اجرا شود"]},answer:0,why:{en:"The heavy call only happens after a human decides the posting is worth it.",fa:"فراخوانی سنگین فقط بعد از اینکه آدمی تصمیم بگیرد آگهی ارزشش را دارد انجام می‌شود."}},{q:{en:"The prompt already forbids closed gaps. Why are they still dropped on the server?",fa:"prompt از قبل gapهای بسته را ممنوع کرده. چرا باز هم روی سرور حذف می‌شوند؟"},options:{en:["Because the prompt is not sent","Because the model has used them anyway, and the dictionary has to hold whoever scored the posting","Because closed gaps are too long"],fa:["چون prompt فرستاده نمی‌شود","چون مدل با این حال از آن‌ها استفاده کرده، و دیکشنری باید برای هر کسی که آگهی را امتیاز داده برقرار باشد","چون gapهای بسته خیلی طولانی‌اند"]},answer:1,why:{en:"A rule in a prompt is a request; a rule in code is enforced, including for the nightly estimates.",fa:"قاعده در prompt یک خواهش است؛ قاعده در کد اجرا می‌شود، از جمله برای برآوردهای شبانه."}},{q:{en:"Why can a draft be re-analyzed but a sent application can not?",fa:"چرا یک draft را می‌شود دوباره تحلیل کرد ولی درخواست فرستاده‌شده را نه؟"},options:{en:["Because sent applications have no posting text","Because re-analysis costs more after sending","Because a sent application's gap tags record what was missing when it went out"],fa:["چون درخواست‌های فرستاده‌شده متن آگهی ندارند","چون تحلیل دوباره بعد از ارسال گران‌تر است","چون gap tagهای درخواست فرستاده‌شده ثبت می‌کنند هنگام ارسال چه چیزی کم بود"]},answer:2,why:{en:"Rewriting them later would change the history that the gap statistics are built on.",fa:"بازنویسی‌شان بعداً تاریخچه‌ای را عوض می‌کرد که آمار gapها روی آن ساخته شده."}}]},{id:"build",group:"ai",title:{en:"Build: why the AI can't invent claims",fa:"Build: چرا AI نمی‌تواند ادعا بسازد"},files:["server/src/app.js","server/src/combinePackage.js","server/scripts/combine_docx.py"],en:[{id:"enum",h:"Every bullet names a real fact",p:["The model never writes free-form claims. Each résumé bullet must carry a `fact_id` from an enum of the fact bank's real ids for that template, so it can't name a fact that doesn't exist; Skills lines are chosen by id and copied word for word."],examples:["enum"]},{id:"guardian",h:"The guardian, before anything is written",p:["`validate.py` then checks every bullet's numbers against that fact's `allowed_numbers` and its `forbidden` phrases, before a single file is written. A missing employment role (a hole in the timeline) is checked here too. A rejected package gets one repair turn: the model sees the guardian's exact errors as a tool result and resubmits."],examples:["roles","repair"]},{id:"warn",h:"Still rejected: built, with warnings",p:["Both calls are already paid for by then, so a package rejected twice is built anyway, and the guardian's errors become warnings to review (in `build_error.json` and `plan.json`) before sending. `plan.json` keeps which fact every bullet came from and what that fact said, which is how the Résumé page links bullets back and Health spots a fact that changed since."],examples:["warnings"]},{id:"lock",h:"One build per folder",p:["`build.py` renders the résumé and cover letter as Word and PDF, then the server adds one combined file of each for portals that take a single upload. A second build of the same folder while one is rendering would race on the same files, so it is refused with 409."],examples:["inflight"]}],fa:[{id:"enum",h:"هر bullet یک fact واقعی را نام می‌برد",p:["مدل هیچ‌وقت ادعای آزاد نمی‌نویسد. هر bullet رزومه باید یک `fact_id` از enumی از idهای واقعی fact bank برای آن قالب داشته باشد، پس نمی‌تواند factی را نام ببرد که وجود ندارد؛ خطوط Skills با id انتخاب و کلمه به کلمه کپی می‌شوند."],examples:["enum"]},{id:"guardian",h:"نگهبان، قبل از نوشتن هر چیز",p:["بعد `validate.py` عددهای هر bullet را با `allowed_numbers` همان fact و عبارت‌های `forbidden` آن چک می‌کند، قبل از این‌که حتی یک فایل نوشته شود. جا افتادن یک سابقه‌ی کاری (حفره‌ای در timeline) هم همین‌جا چک می‌شود. بسته‌ی ردشده یک نوبت اصلاح می‌گیرد: مدل خطاهای دقیق نگهبان را به‌صورت tool result می‌بیند و دوباره می‌فرستد."],examples:["roles","repair"]},{id:"warn",h:"باز هم رد: ساخته می‌شود، با هشدار",p:["تا این‌جا پول هر دو صدا زدن داده شده، پس بسته‌ای که دو بار رد شده باز هم ساخته می‌شود، و خطاهای نگهبان هشدارهایی می‌شوند برای بازبینی (در `build_error.json` و `plan.json`) قبل از فرستادن. `plan.json` نگه می‌دارد هر bullet از کدام fact آمده و آن fact چه می‌گفت، و صفحه‌ی Résumé با همین bulletها را به fact برمی‌گرداند و Health factی را که از آن موقع عوض شده پیدا می‌کند."],examples:["warnings"]},{id:"lock",h:"یک build برای هر پوشه",p:["`build.py` رزومه و cover letter را به‌صورت Word و PDF render می‌کند، بعد سرور از هر کدام یک فایل ترکیبی برای پورتال‌هایی که یک آپلود می‌گیرند اضافه می‌کند. build دوم همان پوشه وسط render روی همان فایل‌ها مسابقه می‌داد، پس با 409 رد می‌شود."],examples:["inflight"]}],examples:{enum:{title:{en:"fact_id is an enum",fa:"fact_id یک enum است"},lang:"javascript",file:"server/src/app.js",from:"bullets: {",lines:11},roles:{title:{en:"A missing role, or the guardian",fa:"سابقه‌ی جاافتاده، یا نگهبان"},lang:"javascript",file:"server/src/app.js",from:"validation = missingRoles.length",lines:10},repair:{title:{en:"At most two attempts",fa:"حداکثر دو تلاش"},lang:"javascript",file:"server/src/app.js",from:"for (let attempt = 0; attempt < 2; attempt++) {",lines:7},warnings:{title:{en:"Errors become warnings",fa:"خطاها هشدار می‌شوند"},lang:"javascript",file:"server/src/app.js",from:"let guardianWarnings = [];",lines:7},inflight:{title:{en:"The in-flight lock",fa:"قفل در جریان"},lang:"javascript",file:"server/src/app.js",from:'app.post("/api/packages/build", async (req, res) => {',lines:17}},quiz:[{q:{en:"How does the fact-id enum stop the model from inventing a claim?",fa:"enum مربوط به fact-id چطور جلوی ساختن ادعا توسط مدل را می‌گیرد؟"},options:{en:["Every bullet must carry a real fact id from the bank, so it can not point at a fact that does not exist","It limits the length of every bullet","It removes numbers from the résumé"],fa:["هر bullet باید یک fact id واقعی از بانک داشته باشد، پس نمی‌تواند به factی اشاره کند که وجود ندارد","طول هر bullet را محدود می‌کند","عددها را از رزومه حذف می‌کند"]},answer:0,why:{en:"The strict schema only accepts ids from the list, and `validate.py` then checks the bullet against that fact.",fa:"schema سخت‌گیر فقط idهای فهرست را می‌پذیرد و بعد `validate.py` bullet را با همان fact مقایسه می‌کند."}},{q:{en:"What does the model get on its single repair turn?",fa:"مدل در تنها نوبت اصلاحش چه چیزی دریافت می‌کند؟"},options:{en:["A fresh prompt without the previous answer","The guardian's exact errors as a tool result, to resubmit","Nothing, the package is built as is"],fa:["یک prompt تازه بدون پاسخ قبلی","خطاهای دقیق guardian به‌صورت tool result، تا دوباره ارسال کند","هیچ، بسته همان‌طور build می‌شود"]},answer:1,why:{en:"Seeing the precise errors lets the model fix just those bullets.",fa:"دیدن خطاهای دقیق به مدل اجازه می‌دهد فقط همان bulletها را درست کند."}},{q:{en:"Why is a second build of the same folder refused with 409 while one is rendering?",fa:"چرا build دوم برای همان پوشه، وقتی یکی در حال render است، با 409 رد می‌شود؟"},options:{en:["Because the API allows one build per day","Because Claude can only answer one request at a time","Because both builds would race on the same output files"],fa:["چون API روزی یک build اجازه می‌دهد","چون Claude هر بار فقط به یک درخواست پاسخ می‌دهد","چون هر دو build روی همان فایل‌های خروجی مسابقه می‌دادند"]},answer:2,why:{en:"The in-flight set holds the folder until the render finishes, so the files are never written by two builds at once.",fa:"مجموعه‌ی در حال اجرا پوشه را تا پایان render نگه می‌دارد، پس فایل‌ها هیچ‌وقت هم‌زمان توسط دو build نوشته نمی‌شوند."}}]},{id:"assistant",group:"ai",title:{en:"The assistant: ask the ledger",fa:"دستیار: از ledger بپرس"},files:["server/src/assistant.js","client/src/components/AssistantPanel.jsx"],en:[{id:"endpoint",h:"Read-only, from a snapshot",p:["*What should I do today?* gives a briefing (interviews coming up, follow-ups due, drafts waiting for approval, then patterns), and any question can be asked in English or Persian, with follow-ups. Claude sees a compact snapshot of the ledger with the pipeline already computed, and no contact names, emails or files. Nothing is ever changed."],data:{kind:"endpoints",only:["assistant"]},examples:["snapshot"]},{id:"shape",h:"An answer in a fixed shape",p:["The reply is structured JSON output against a schema: the answer text, and actions with a title, a reason, a priority and the folder they are about, so each action can open its application. The snapshot is a cached block, so follow-up questions read it at the cached price."],examples:["schema","call"]},{id:"history",h:"Follow-ups without server memory",p:["The server keeps no conversation. The panel sends the earlier turns back with each question, and `validateAssistantRequest` keeps at most the last six, each question cut to 2,000 characters and each answer to 4,000, so a long chat can not grow the request without limit. The mode has to be `brief` or `ask`, and `ask` needs a question.","Each turn becomes a user message and an assistant message before the new question, while the snapshot stays in the cached system block. The usage of these calls is filed under `applications/_assistant`, a name no real application can have, since real folder names start with a letter or a digit."],examples:["request"]},{id:"folders",h:"A folder it made up is dropped",p:["Before the answer leaves the server, every action's folder is checked against the snapshot: one the model made up becomes null rather than a link to nowhere. A refusal or a cut-off answer becomes a clear message, and its cost is still recorded.","A refusal answers 422 and asks you to rephrase; a cut-off answer or text that is not valid JSON answers 502. The priority is also forced to high, medium or low, so the panel never has to handle a value it does not know."],examples:["known"]}],fa:[{id:"endpoint",h:"فقط‌خواندنی، از یک snapshot",p:["*What should I do today?* یک گزارش روز می‌دهد (مصاحبه‌های نزدیک، پیگیری‌هایی که وقتشان شده، پیش‌نویس‌هایی که منتظر تأییدند، بعد الگوها)، و هر سؤالی را می‌شود به انگلیسی یا فارسی پرسید، با سؤال‌های بعدی. Claude یک snapshot فشرده از ledger را می‌بیند که pipeline در آن از قبل حساب شده، بدون اسم مخاطب، ایمیل یا فایل. هیچ چیز هیچ‌وقت عوض نمی‌شود."],data:{kind:"endpoints",only:["assistant"]},examples:["snapshot"]},{id:"shape",h:"جواب با یک شکل ثابت",p:["پاسخ، خروجی JSON ساختاریافته در برابر یک schema است: متن جواب، و actionهایی با عنوان، دلیل، اولویت و پوشه‌ای که درباره‌اش هستند، تا هر action بتواند درخواست خودش را باز کند. snapshot یک بلوک cache‌شده است، پس سؤال‌های بعدی آن را با قیمت cache می‌خوانند."],examples:["schema","call"]},{id:"history",h:"پرسش‌های بعدی بدون حافظه‌ی سرور",p:["سرور هیچ گفت‌وگویی نگه نمی‌دارد. پنل نوبت‌های قبلی را با هر پرسش پس می‌فرستد، و `validateAssistantRequest` حداکثر شش نوبت آخر را نگه می‌دارد، هر پرسش را به ۲۰۰۰ نویسه و هر پاسخ را به ۴۰۰۰ نویسه کوتاه می‌کند، تا یک گفت‌وگوی طولانی درخواست را بی‌حد بزرگ نکند. حالت باید `brief` یا `ask` باشد و `ask` پرسش لازم دارد.","هر نوبت پیش از پرسش تازه به یک پیام user و یک پیام assistant تبدیل می‌شود، در حالی که snapshot در بلوک system کش‌شده می‌ماند. مصرف این فراخوانی‌ها زیر `applications/_assistant` ثبت می‌شود، نامی که هیچ درخواست واقعی نمی‌تواند داشته باشد، چون نام پوشه‌های واقعی با حرف یا رقم شروع می‌شود."],examples:["request"]},{id:"folders",h:"پوشه‌ی ساختگی حذف می‌شود",p:["قبل از این‌که جواب از سرور بیرون برود، پوشه‌ی هر action با snapshot چک می‌شود: پوشه‌ای که مدل از خودش ساخته null می‌شود نه لینکی به هیچ‌جا. امتناع یا جواب بریده یک پیام روشن می‌شود، و هزینه‌اش باز هم ثبت می‌شود.","امتناع با 422 پاسخ می‌گیرد و می‌خواهد پرسش را جور دیگری بنویسید؛ پاسخ بریده‌شده یا متنی که JSON معتبر نیست 502 می‌گیرد. اولویت هم به high، medium یا low محدود می‌شود، تا پنل هرگز با مقداری که نمی‌شناسد روبه‌رو نشود."],examples:["known"]}],examples:{snapshot:{title:{en:"What the model sees",fa:"چیزی که مدل می‌بیند"},lang:"javascript",file:"server/src/assistant.js",from:"export function ledgerSnapshot(rows, now = new Date()) {",lines:26},schema:{title:{en:"An action's folder",fa:"پوشه‌ی یک action"},lang:"javascript",file:"server/src/assistant.js",from:"folder: {",lines:4},call:{title:{en:"JSON output, a cached snapshot",fa:"خروجی JSON، snapshot cache‌شده"},lang:"javascript",file:"server/src/assistant.js",from:"const message = await client.beta.messages.create({",lines:15},known:{title:{en:"Only folders that exist",fa:"فقط پوشه‌هایی که وجود دارند"},lang:"javascript",file:"server/src/assistant.js",from:"const known = new Set(snapshot.applications.map((a) => a.folder));",lines:7},request:{title:{en:"The request, checked and trimmed",fa:"درخواست، بررسی‌شده و کوتاه‌شده"},lang:"javascript",file:"server/src/assistant.js",from:"export function validateAssistantRequest(body) {",lines:12}},quiz:[{q:{en:"Why does Claude get a compact snapshot instead of the raw ledger?",fa:"چرا Claude به جای ledger خام یک snapshot فشرده می‌گیرد؟"},options:{en:["Because the raw ledger is in Persian","So it never sees contact names, emails or files, and the pipeline arrives already computed","Because the API does not accept CSV"],fa:["چون ledger خام فارسی است","تا هرگز نام contact، ایمیل یا فایل نبیند و pipeline از پیش محاسبه‌شده برسد","چون API فایل CSV نمی‌پذیرد"]},answer:1,why:{en:"The snapshot holds only what a progress question needs, nothing that identifies a contact.",fa:"snapshot فقط چیزی را دارد که یک پرسش درباره‌ی پیشرفت لازم دارد، هیچ چیزی که contactی را شناسایی کند."}},{q:{en:"The model suggests an action about a folder that is not in the snapshot. What happens?",fa:"مدل اقدامی درباره‌ی پوشه‌ای پیشنهاد می‌کند که در snapshot نیست. چه می‌شود؟"},options:{en:["The folder becomes null, so the action shows without a link to nowhere","The whole answer is rejected","A new draft is created for it"],fa:["پوشه null می‌شود، پس اقدام بدون لینک به ناکجا نشان داده می‌شود","کل پاسخ رد می‌شود","برایش یک draft تازه ساخته می‌شود"]},answer:0,why:{en:"Every folder is checked against the set of known folders before the answer leaves the server.",fa:"هر پوشه پیش از خروج پاسخ از سرور با مجموعه‌ی پوشه‌های شناخته‌شده مقایسه می‌شود."}},{q:{en:"How do follow-up questions keep their context?",fa:"پرسش‌های بعدی چطور زمینه‌شان را نگه می‌دارند؟"},options:{en:["The server stores the conversation in a session","Claude remembers earlier calls","The panel sends the earlier turns back, and the server keeps the last six"],fa:["سرور گفت‌وگو را در session نگه می‌دارد","Claude فراخوانی‌های قبلی را به یاد دارد","پنل نوبت‌های قبلی را پس می‌فرستد و سرور شش‌تای آخر را نگه می‌دارد"]},answer:2,why:{en:"The server is stateless here; the history travels with each request and is trimmed there.",fa:"سرور اینجا بی‌حالت است؛ تاریخچه با هر درخواست می‌آید و همان‌جا کوتاه می‌شود."}}]},{id:"costs",group:"ai",title:{en:"What each call cost, and a spending brake",fa:"هزینه‌ی هر صدا زدن، و ترمز خرج"},files:["server/src/aiUsage.js","server/src/app.js","client/src/pages/CostsPage.jsx","client/src/api.js"],en:[{id:"filed",h:"Filed with the package",p:["Every Claude call adds one JSON line to `applications/<folder>/ai_usage.jsonl`: tokens in, cache reads and writes, tokens out and the price in USD. The folder is the one place a release never overwrites, and the server log, which held these numbers before, is wiped on each restart. A call that failed after it was answered is filed all the same."],data:{kind:"endpoints",only:["usage"]},examples:["prices","before"]},{id:"price",h:"The price of a call",p:["Input, cache reads, cache writes and output each at their own rate per million tokens. A model missing from the table is priced as Sonnet and flagged, rather than counted as free. The Costs page totals the month against `AI_MONTHLY_BUDGET`."],examples:["cost"]},{id:"brake",h:"Only a click spends money",p:["Every Claude call has to start from a button in the dashboard: the page marks those requests with `X-AI-Request: app`. A script (the nightly search, a curl) is refused unless `AI_SCRIPT_CALLS` lets it in; it can save a posting as a draft instead, to analyze from its page later. This is a spending brake, not security: anyone already past the login could send the header."],examples:["brake","header"]}],fa:[{id:"filed",h:"همراه بسته ثبت می‌شود",p:["هر صدا زدن Claude یک خط JSON به `applications/<folder>/ai_usage.jsonl` اضافه می‌کند: tokenهای ورودی، خواندن و نوشتن cache، tokenهای خروجی و قیمت به دلار. این پوشه تنها جایی است که release هیچ‌وقت رونویسی نمی‌کند، و log سرور، که قبلاً این عددها را داشت، با هر restart پاک می‌شود. صدا زدنی که بعد از جواب گرفتن شکست خورده هم همان‌طور ثبت می‌شود."],data:{kind:"endpoints",only:["usage"]},examples:["prices","before"]},{id:"price",h:"قیمت یک صدا زدن",p:["ورودی، خواندن cache، نوشتن cache و خروجی هر کدام با نرخ خودشان به ازای یک میلیون token. مدلی که در جدول نیست با قیمت Sonnet حساب و علامت زده می‌شود، نه مجانی. صفحه‌ی Costs جمع ماه را در برابر `AI_MONTHLY_BUDGET` نشان می‌دهد."],examples:["cost"]},{id:"brake",h:"فقط کلیک پول خرج می‌کند",p:["هر صدا زدن Claude باید از یک دکمه در داشبورد شروع شود: صفحه آن درخواست‌ها را با `X-AI-Request: app` علامت می‌زند. اسکریپت (جست‌وجوی شبانه، یک curl) رد می‌شود مگر `AI_SCRIPT_CALLS` راهش بدهد؛ به‌جایش می‌تواند آگهی را به‌صورت پیش‌نویس ذخیره کند تا بعداً از صفحه‌اش analyze شود. این ترمز خرج است، نه امنیت: هر کسی که از ورود رد شده می‌تواند این هدر را بفرستد."],examples:["brake","header"]}],examples:{prices:{title:{en:"Prices per million tokens",fa:"قیمت به ازای یک میلیون token"},lang:"javascript",file:"server/src/aiUsage.js",from:"const PRICES = {",lines:6},before:{title:{en:"Paid for, even if it fails next",fa:"پولش داده شده، حتی اگر بعدش شکست بخورد"},lang:"javascript",file:"server/src/app.js",from:"// Filed before normalizeAnalysis, which can still throw",lines:3},cost:{title:{en:"The cost of one call",fa:"هزینه‌ی یک صدا زدن"},lang:"javascript",file:"server/src/aiUsage.js",from:"export function costOf(model, usage) {",lines:11},brake:{title:{en:"The spending brake",fa:"ترمز خرج"},lang:"javascript",file:"server/src/app.js",from:"const AI_ROUTES = {",lines:17},header:{title:{en:"What the page sends",fa:"چیزی که صفحه می‌فرستد"},lang:"javascript",file:"client/src/api.js",from:"const AI_HEADERS",lines:1}},quiz:[{q:{en:"Why is each call's usage written into the application's folder instead of only the server log?",fa:"چرا مصرف هر فراخوانی در پوشه‌ی درخواست نوشته می‌شود و نه فقط در log سرور؟"},options:{en:["The log is wiped on each restart, and the folder is the one place a release never overwrites","Because the folder is faster to write","Because the log can not hold JSON"],fa:["log با هر راه‌اندازی دوباره پاک می‌شود و پوشه تنها جایی است که release هرگز بازنویسی نمی‌کند","چون نوشتن در پوشه سریع‌تر است","چون log نمی‌تواند JSON نگه دارد"]},answer:0,why:{en:"The numbers have to survive restarts and releases to be totalled for the month.",fa:"عددها باید از راه‌اندازی دوباره و release جان سالم به در ببرند تا برای ماه جمع زده شوند."}},{q:{en:"A model is missing from the price table. How is its call priced?",fa:"مدلی در جدول قیمت نیست. فراخوانی‌اش چطور قیمت‌گذاری می‌شود؟"},options:{en:["As free","As Sonnet, and flagged","The call is refused"],fa:["رایگان","به قیمت Sonnet، با یک علامت","فراخوانی رد می‌شود"]},answer:1,why:{en:"Counting it as free would hide real spending; a known price with a flag is the safer error.",fa:"رایگان حساب کردنش هزینه‌ی واقعی را پنهان می‌کرد؛ یک قیمت معلوم همراه علامت، خطای امن‌تری است."}},{q:{en:"Why is the `X-AI-Request: app` header called a spending brake rather than security?",fa:"چرا header `X-AI-Request: app` ترمز هزینه نامیده می‌شود و نه امنیت؟"},options:{en:["Because it is encrypted","Because only Claude can send it","Because anyone already past the login could send it; it only stops scripts from spending by accident"],fa:["چون رمزنگاری شده","چون فقط Claude می‌تواند آن را بفرستد","چون هر کسی که از login گذشته می‌تواند آن را بفرستد؛ فقط جلوی خرج کردن تصادفی اسکریپت‌ها را می‌گیرد"]},answer:2,why:{en:"Access is decided by the login and the token; the header only makes paid calls start from a click.",fa:"دسترسی را login و token تعیین می‌کنند؛ header فقط باعث می‌شود فراخوانی‌های پولی از یک کلیک شروع شوند."}}]},{id:"truth-bank",group:"truth",title:{en:"Editing the truth bank safely",fa:"ویرایش امن بانک حقیقت"},files:["server/src/truthBank.js","server/src/truthRoutes.js","server/src/engineGit.js","client/src/pages/TruthBankPage.jsx"],en:[{id:"endpoints",h:"Endpoints",p:["Every fact in `facts/*.yml`, grouped by project or role, with the gaps it is evidence for and the built résumés that used it. Facts can be added, edited and removed here."],data:{kind:"endpoints",only:["truth-bank"]}},{id:"surgical",h:"Only that fact's lines change",p:["A full YAML re-dump reformatted about 1,500 lines per file and lost every comment. So a save finds the edited fact's own lines (from its `- id:` to the next item) and replaces only those; everything else stays byte for byte, CRLF files included. A fact's id can't be renamed, since gaps and built résumés refer to it."],examples:["spans","rename"]},{id:"readback",h:"Parsed back before it's written",p:["The new file text is parsed again and compared before it touches the disk: the fact must read back exactly as asked, and the file must have the same number of facts (one more for a new fact). A formatting slip can't silently change a claim."],examples:["checked"]},{id:"git",h:"Every save is a commit",p:["The engine folder is a local git repo with no remote, and every save from the dashboard is one commit with the fact id in its message, so a fact's history is a real diff (🕘) instead of a pile of `.bak` files. Without git, or without the repo, a save still works and just goes unrecorded."],examples:["commit"]}],fa:[{id:"endpoints",h:"endpointها",p:["هر fact در `facts/*.yml`، گروه‌بندی‌شده بر اساس پروژه یا نقش، با gapهایی که برایشان شاهد است و رزومه‌های ساخته‌شده‌ای که از آن استفاده کرده‌اند. factها را همین‌جا می‌شود اضافه، ویرایش و حذف کرد."],data:{kind:"endpoints",only:["truth-bank"]}},{id:"surgical",h:"فقط خطوط همان fact عوض می‌شوند",p:["dump دوباره‌ی کل YAML حدود ۱,۵۰۰ خط از هر فایل را دوباره قالب‌بندی می‌کرد و همه‌ی comment‌ها را از دست می‌داد. پس ذخیره خطوط خود fact ویرایش‌شده را پیدا می‌کند (از `- id:`ش تا آیتم بعدی) و فقط همان‌ها را عوض می‌کند؛ بقیه بایت به بایت می‌مانند، فایل‌های CRLF هم. id یک fact عوض نمی‌شود، چون gapها و رزومه‌های ساخته‌شده به آن اشاره می‌کنند."],examples:["spans","rename"]},{id:"readback",h:"قبل از نوشتن دوباره خوانده می‌شود",p:["متن تازه‌ی فایل قبل از این‌که به دیسک برسد دوباره parse و مقایسه می‌شود: fact باید دقیقاً همان‌طور که خواسته شده خوانده شود، و فایل باید همان تعداد fact را داشته باشد (برای fact تازه یکی بیشتر). یک لغزش قالب‌بندی نمی‌تواند بی‌صدا یک ادعا را عوض کند."],examples:["checked"]},{id:"git",h:"هر ذخیره یک commit است",p:["پوشه‌ی موتور یک repo محلی git بدون remote است، و هر ذخیره از داشبورد یک commit با id آن fact در پیامش، پس تاریخچه‌ی یک fact یک diff واقعی است (🕘) نه انبوهی از فایل‌های `.bak`. بدون git، یا بدون repo، ذخیره باز هم کار می‌کند و فقط ثبت نمی‌شود."],examples:["commit"]}],examples:{spans:{title:{en:"Where each fact's lines are",fa:"خطوط هر fact کجاست"},lang:"javascript",file:"server/src/truthBank.js",from:"function itemSpans(lines) {",lines:13},rename:{title:{en:"An id stays",fa:"id می‌ماند"},lang:"javascript",file:"server/src/truthBank.js",from:"if (!create && fact.id !== id) {",lines:3},checked:{title:{en:"Read back, or nothing is written",fa:"دوباره خوانده شود، وگرنه هیچ چیز نوشته نمی‌شود"},lang:"javascript",file:"server/src/truthBank.js",from:'writeChecked(filePath, lines.join("\\n"), (parsed) => {',lines:8},commit:{title:{en:"One commit per save",fa:"یک commit برای هر ذخیره"},lang:"javascript",file:"server/src/engineGit.js",from:"async function commit(paths, message) {",lines:17}},quiz:[{q:{en:"Why does a save replace only the edited fact's lines instead of re-dumping the YAML?",fa:"چرا ذخیره فقط خط‌های fact ویرایش‌شده را جایگزین می‌کند و YAML را از نو dump نمی‌کند؟"},options:{en:["A full re-dump reformatted about 1,500 lines per file and lost every comment","Re-dumping is not possible in Node","To make the file smaller"],fa:["dump کامل حدود ۱۵۰۰ خط در هر فایل را دوباره قالب‌بندی می‌کرد و همه‌ی comment‌ها را از بین می‌برد","dump دوباره در Node ممکن نیست","تا فایل کوچک‌تر شود"]},answer:0,why:{en:"Everything outside the fact's own span stays byte for byte, so the diff shows only the real change.",fa:"هر چیزی بیرون از محدوده‌ی خود fact بایت به بایت می‌ماند، پس diff فقط تغییر واقعی را نشان می‌دهد."}},{q:{en:"Why can a fact's id not be renamed from the dashboard?",fa:"چرا id یک fact را نمی‌شود از داشبورد تغییر نام داد؟"},options:{en:["Because ids are generated by git","Because gaps and built résumés refer to it by that id","Because YAML keys are read-only"],fa:["چون idها را git می‌سازد","چون gapها و رزومه‌های ساخته‌شده با همان id به آن اشاره می‌کنند","چون کلیدهای YAML فقط‌خواندنی‌اند"]},answer:1,why:{en:"Renaming would silently break every reference to the fact.",fa:"تغییر نام همه‌ی ارجاع‌ها به آن fact را بی‌صدا می‌شکست."}},{q:{en:"What does parsing the new file text back before writing protect against?",fa:"دوباره parse کردن متن فایل تازه پیش از نوشتن، از چه چیزی محافظت می‌کند؟"},options:{en:["A slow disk","Two users saving at once","A formatting slip silently changing a claim or losing a fact"],fa:["دیسک کند","ذخیره‌ی هم‌زمان دو کاربر","یک لغزش قالب‌بندی که بی‌صدا ادعایی را عوض کند یا factی را گم کند"]},answer:2,why:{en:"The fact must read back exactly as asked and the file must keep the same number of facts.",fa:"fact باید دقیقاً همان‌طور که خواسته شده خوانده شود و فایل باید همان تعداد fact را نگه دارد."}}]},{id:"health",group:"truth",title:{en:"Gaps, résumés and Health",fa:"gapها، رزومه‌ها و Health"},files:["server/src/health.js","server/src/truthRoutes.js","server/src/truthBank.js","client/src/pages/HealthPage.jsx","client/src/pages/GapsPage.jsx"],en:[{id:"endpoints",h:"Endpoints",p:["Gaps: the gap dictionary with each gap's status, its evidence and the postings tagged with it. Résumé: the templates as the engine reads them, and every built résumé with each bullet linked to its fact. Health: where the pieces disagree."],data:{kind:"endpoints",only:["gaps","resume","health"]}},{id:"status",h:"A gap's status is in its own words",p:[`Whether a gap is open, partial or closed is read from its label's Persian wording ("بسته شد" closed, with "همچنان/باقی/هنوز" partial), the same rule the Context engine uses, so the dictionary text is the only place a status lives.`],examples:["status"]},{id:"checks",h:"Every check was a real mistake once",p:["Health lists where the truth bank, the gap dictionary, the templates and the drafts disagree: a technology tag a fact's claim never names (the model only reads claims), an open gap with tagged evidence but no citation, a label citing a fact that no longer exists, drafts scored before the truth bank changed or built from facts that changed since, files edited outside the dashboard. Each one is there because it happened and had to be found by hand."],examples:["why","stem"]},{id:"stale",h:"Stale, exactly",p:["Every analysis saves a short hash of the facts and gap labels it read. A draft whose hash differs from today's was scored against an older truth bank, exactly, not guessed from file dates; it can be re-analyzed on its own or with all the others."],examples:["fingerprint","staleFlag"]}],fa:[{id:"endpoints",h:"endpointها",p:["Gaps: دیکشنری gap با وضعیت هر gap، شاهدش و آگهی‌هایی که با آن برچسب خورده‌اند. Résumé: قالب‌ها همان‌طور که موتور می‌خواند، و هر رزومه‌ی ساخته‌شده با هر bullet وصل به factش. Health: جاهایی که تکه‌ها با هم نمی‌خوانند."],data:{kind:"endpoints",only:["gaps","resume","health"]}},{id:"status",h:"وضعیت gap در کلمات خودش است",p:["باز، نیمه یا بسته بودن یک gap از متن فارسی برچسبش خوانده می‌شود («بسته شد» بسته، با «همچنان/باقی/هنوز» نیمه)، همان قانونی که موتور Context به کار می‌برد، پس متن دیکشنری تنها جایی است که وضعیت زندگی می‌کند."],examples:["status"]},{id:"checks",h:"هر چک یک بار اشتباهی واقعی بوده",p:["Health فهرست می‌کند کجا بانک حقیقت، دیکشنری gap، قالب‌ها و پیش‌نویس‌ها با هم نمی‌خوانند: tag فناوری‌ای که ادعای fact هیچ‌وقت نامش را نمی‌برد (مدل فقط ادعاها را می‌خواند)، gap بازی با شاهد برچسب‌خورده ولی بی‌ارجاع، برچسبی که به factی ارجاع می‌دهد که دیگر نیست، پیش‌نویس‌هایی که قبل از تغییر بانک حقیقت امتیاز گرفته‌اند یا از factهایی ساخته شده‌اند که بعد عوض شده‌اند، فایل‌هایی که بیرون از داشبورد ویرایش شده‌اند. هر کدام آن‌جاست چون اتفاق افتاده و باید با دست پیدا می‌شد."],examples:["why","stem"]},{id:"stale",h:"کهنه، دقیقاً",p:["هر analysis یک hash کوتاه از factها و برچسب‌های gapی که خوانده ذخیره می‌کند. پیش‌نویسی که hashش با امروز فرق دارد در برابر بانک حقیقت قدیمی‌تری امتیاز گرفته، دقیقاً، نه حدس از تاریخ فایل‌ها؛ می‌شود آن را تنها یا همراه همه‌ی بقیه دوباره analyze کرد."],examples:["fingerprint","staleFlag"]}],examples:{status:{title:{en:"Status from the label",fa:"وضعیت از برچسب"},lang:"javascript",file:"server/src/truthBank.js",from:"export function gapStatus(label) {",lines:6},why:{title:{en:"Why these checks exist",fa:"چرا این چک‌ها هستند"},lang:"javascript",file:"server/src/health.js",from:"// Consistency checks across",lines:8},stem:{title:{en:"Does a claim name its tag?",fa:"ادعا tagش را نام می‌برد؟"},lang:"javascript",file:"server/src/health.js",from:"const stemLast = (tag) =>",lines:12},fingerprint:{title:{en:"The truth bank's fingerprint",fa:"اثر انگشت بانک حقیقت"},lang:"javascript",file:"server/src/truthBank.js",from:"export function bankFingerprint(factsDir, gapTagsPath) {",lines:8},staleFlag:{title:{en:"A draft that went stale",fa:"پیش‌نویسی که کهنه شده"},lang:"javascript",file:"server/src/truthRoutes.js",from:"// Old drafts have no saved fingerprint",lines:3}},quiz:[{q:{en:"Where does a gap's status (open, partial, closed) come from?",fa:"وضعیت یک gap (باز، نیمه، بسته) از کجا می‌آید؟"},options:{en:["From its label's own Persian wording, the only place a status lives","From a separate status column","From Claude's analysis"],fa:["از عبارت فارسی خود برچسبش، تنها جایی که وضعیت زندگی می‌کند","از یک ستون وضعیت جداگانه","از تحلیل Claude"]},answer:0,why:{en:"Keeping the status in the text means it can never disagree with a second copy.",fa:"نگه داشتن وضعیت در خود متن یعنی هیچ‌وقت با نسخه‌ی دومی ناسازگار نمی‌شود."}},{q:{en:"How does Health know a draft was scored against an older truth bank?",fa:"Health از کجا می‌فهمد یک draft با بانک حقیقت قدیمی‌تری امتیاز گرفته؟"},options:{en:["From the file dates of the facts","The analysis saved a short hash of the facts and gap labels, and it differs from today's","From the git log"],fa:["از تاریخ فایل‌های fact","تحلیل یک هش کوتاه از factها و برچسب‌های gap ذخیره کرده که با هش امروز فرق دارد","از git log"]},answer:1,why:{en:"A fingerprint compares exactly what was read, rather than guessing from timestamps.",fa:"اثر انگشت دقیقاً همان چیزی را که خوانده شده مقایسه می‌کند، نه اینکه از زمان‌ها حدس بزند."}},{q:{en:"Why does Health flag a technology tag that a fact's claim never names?",fa:"چرا Health تگ فناوری‌ای را علامت می‌زند که ادعای fact هرگز نامش را نمی‌آورد؟"},options:{en:["Because tags are not allowed","Because it makes the YAML invalid","Because the model only reads claims, so a tag the claim does not support is invisible evidence"],fa:["چون تگ مجاز نیست","چون YAML را نامعتبر می‌کند","چون مدل فقط ادعاها را می‌خواند، پس تگی که ادعا پشتیبانی‌اش نمی‌کند مدرکی نامرئی است"]},answer:2,why:{en:"Each check exists because the mismatch actually happened once and had to be found by hand.",fa:"هر بررسی به این دلیل هست که این ناسازگاری واقعاً یک بار رخ داده و باید دستی پیدا می‌شد."}}]},{id:"fe-app",group:"frontend",title:{en:"The pages and the API client",fa:"صفحه‌ها و API client"},files:["client/src/App.jsx","client/src/api.js","client/src/components/LoginGate.jsx","client/vite.config.js"],en:[{id:"routes",h:"Routes",p:["React with Vite and Bootstrap, `HashRouter`, one page per part of the search. The navbar, the daily line, the scroll control and the assistant panel are on every page.","`LoginGate` wraps the whole `HashRouter`, so no page mounts, and no page fires an API call, until the gate knows the session is good. With a hash router the part after `#` never reaches the server: every page is the same `index.html`, and reloading `/#/pipeline` works without any server-side route."],data:{kind:"routes"},examples:["shell"]},{id:"gate",h:"The login, only when there is one",p:["`LoginGate` asks the server whether a password is required. Locally it isn't and the app opens at once; deployed, a password form shows until the session cookie is set. If the check itself fails, it opens rather than locking a local user out: the server still refuses what needs a session.","While the check is running the gate renders nothing, so the login form does not flash for a local user. A wrong password shows the server's own message, which is also how the 15-minute lockout after five tries becomes visible instead of looking like another wrong password."],examples:["gate"]},{id:"served",h:"Served by the API itself",p:["In production the built app is served by the Express server, so API calls are same-origin with a relative base. Under `vite dev` the page runs on :5173 and calls :4310, which is why that one origin is allowed outside production.","The server registers the static files and an `index.html` fallback after every API route, and the fallback skips anything under `/api/`, so a mistyped API path still answers as an API error rather than with the page. Without a client build the server simply serves the API alone."],examples:["base","static"]}],fa:[{id:"routes",h:"routeها",p:["React با Vite و Bootstrap، `HashRouter`، یک صفحه برای هر بخش جست‌وجو. navbar، خط روز، کنترل اسکرول و پنل دستیار در همه‌ی صفحه‌ها هستند.","`LoginGate` کل `HashRouter` را در بر می‌گیرد، پس هیچ صفحه‌ای mount نمی‌شود و هیچ صفحه‌ای درخواست API نمی‌فرستد تا وقتی دروازه بداند session درست است. با hash router، بخش بعد از `#` هرگز به سرور نمی‌رسد: همه‌ی صفحه‌ها همان `index.html` هستند و reload کردن `/#/pipeline` بدون هیچ route سمت سرور کار می‌کند."],data:{kind:"routes"},examples:["shell"]},{id:"gate",h:"ورود، فقط وقتی هست",p:["`LoginGate` از سرور می‌پرسد رمز لازم است یا نه. در حالت محلی لازم نیست و اپ همان لحظه باز می‌شود؛ روی سرور، فرم رمز تا وقتی کوکی session تنظیم نشده نشان داده می‌شود. اگر خود این پرسش شکست بخورد، به‌جای قفل کردن کاربر محلی باز می‌شود: سرور باز هم چیزی را که session لازم دارد رد می‌کند.","تا بررسی در جریان است، دروازه چیزی render نمی‌کند، پس فرم login برای کاربر محلی یک لحظه هم ظاهر نمی‌شود. رمز اشتباه پیام خود سرور را نشان می‌دهد، و قفل ۱۵ دقیقه‌ای بعد از پنج تلاش هم همین‌طور دیده می‌شود، نه اینکه شبیه یک رمز اشتباه دیگر به نظر برسد."],examples:["gate"]},{id:"served",h:"سرو شده به دست خود API",p:["در production اپ build‌شده را سرور Express سرو می‌کند، پس درخواست‌های API با یک base نسبی same-origin هستند. زیر `vite dev` صفحه روی :5173 اجرا می‌شود و :4310 را صدا می‌زند، و به همین دلیل همین یک origin بیرون از production مجاز است.","سرور فایل‌های static و fallback به `index.html` را بعد از همه‌ی routeهای API ثبت می‌کند، و fallback هر چیزی زیر `/api/` را رد می‌کند، تا مسیر API اشتباه‌تایپ‌شده باز هم خطای API بگیرد و نه صفحه را. بدون build کلاینت، سرور فقط API را سرو می‌کند."],examples:["base","static"]}],examples:{gate:{title:{en:"Is a password needed?",fa:"رمز لازم است؟"},lang:"javascript",file:"client/src/components/LoginGate.jsx",from:"useEffect(() => {",lines:5},base:{title:{en:"A relative base in production",fa:"base نسبی در production"},lang:"javascript",file:"client/src/api.js",from:"const API_BASE",lines:1},static:{title:{en:"The built app, and client-side routes",fa:"اپ build‌شده، و routeهای سمت client"},lang:"javascript",file:"server/src/app.js",from:"// Serve the built React app",lines:8},shell:{title:{en:"The gate around the whole router",fa:"دروازه دور کل router"},lang:"javascript",file:"client/src/App.jsx",from:"<LoginGate>",to:"<Routes>"}},quiz:[{q:{en:"If the session check itself fails, why does `LoginGate` open the app instead of locking it?",fa:"اگر خود بررسی session شکست بخورد، چرا `LoginGate` اپ را باز می‌کند و قفلش نمی‌کند؟"},options:{en:["So a local user is not locked out, while the server still refuses anything that needs a session","Because the password is checked in the browser","Because errors mean the user is already logged in"],fa:["تا کاربر محلی پشت در نماند، در حالی که سرور هنوز هر چیزی را که session لازم دارد رد می‌کند","چون رمز در مرورگر بررسی می‌شود","چون خطا یعنی کاربر از قبل وارد شده"]},answer:0,why:{en:"The gate is a convenience; the real protection is on the server, so failing open in the browser costs nothing.",fa:"دروازه فقط یک راحتی است؛ محافظت واقعی روی سرور است، پس باز شدن در مرورگر هنگام خطا هزینه‌ای ندارد."}},{q:{en:"Why does the built app use an empty `API_BASE`, while `vite dev` uses http://localhost:4310?",fa:"چرا اپ build‌شده `API_BASE` خالی دارد ولی `vite dev` از http://localhost:4310 استفاده می‌کند؟"},options:{en:["Because production has no API","Because in production the Express server serves the app, so calls are same-origin; in dev the page runs on :5173","Because Vite can not make relative requests"],fa:["چون production API ندارد","چون در production سرور Express خود اپ را سرو می‌کند، پس درخواست‌ها هم‌origin‌اند؛ در dev صفحه روی :5173 اجرا می‌شود","چون Vite نمی‌تواند درخواست نسبی بفرستد"]},answer:1,why:{en:"That is also why the :5173 origin is the one foreign origin allowed outside production.",fa:"به همین دلیل origin :5173 تنها origin غریبه‌ای است که بیرون از production مجاز است."}},{q:{en:"Why does reloading a page such as `/#/pipeline` work without a server route for it?",fa:"چرا reload کردن صفحه‌ای مثل `/#/pipeline` بدون route سمت سرور کار می‌کند؟"},options:{en:["The server has a route per page","The browser caches every page","With `HashRouter` the part after `#` never reaches the server, which always serves `index.html`"],fa:["سرور برای هر صفحه یک route دارد","مرورگر همه‌ی صفحه‌ها را cache می‌کند","با `HashRouter` بخش بعد از `#` هرگز به سرور نمی‌رسد و سرور همیشه `index.html` را سرو می‌کند"]},answer:2,why:{en:"Routing happens entirely in the browser from the hash.",fa:"مسیریابی کاملاً در مرورگر و از روی hash انجام می‌شود."}}]},{id:"stores",group:"data",title:{en:"Two stores, one interface",fa:"دو store، یک interface"},files:["server/src/stores/index.js","server/src/stores/csvStore.js","server/src/stores/sqlStore.js","server/src/stores/shape.js"],en:[{id:"same",h:"CSV files or SQL Server",p:['`STORE=csv` (the default) keeps using `ledger.csv`, `pipeline.csv`, `target_list.csv` and `pipeline_stages.yml`; `STORE=sql` uses SQL Server. Both return the same rows: dates as `YYYY-MM-DD` strings and empty text as "", exactly as the CSV had it, so the rest of the server never knows which one it talks to. The fact bank, the gap dictionary and the application folders stay files either way: they are hand-curated or binary.'],examples:["open"]},{id:"shape",h:"The shape both stores return",p:["`shape.js` holds the contract: the ledger and recruiter columns with the same names `ledger.csv` and `target_list.csv` always had, so the client never knows which store is behind the API. Gap tags are a comma-joined list in the API even though SQL keeps them as rows of their own; `splitGapTags` keeps their order and drops blanks and repeats.","A recruiter has no folder, so its id is a short SHA-1 of the LinkedIn URL (unique per person), falling back to name and company. That keeps the same rule as applications: an update never depends on the row's position. The API test suite runs once per store, so if the two ever returned a different shape, a test would fail."],examples:["columns","recruiterId"]},{id:"csv",h:"The CSV store",p:["Every read-modify-write runs synchronously inside one method, so two requests in this process can't interleave between the read and the write."],examples:["sync"]},{id:"sql",h:"The SQL store",p:["A new application, its gap tags and its first draft event go in one transaction. Dates are formatted by SQL Server itself (style 23), so no JavaScript time-zone conversion ever touches them. A value the database refuses (bad date, too long, a constraint) answers 400, not 500."],examples:["create","select","errors"]}],fa:[{id:"same",h:"فایل‌های CSV یا SQL Server",p:['`STORE=csv` (پیش‌فرض) همان `ledger.csv`، `pipeline.csv`، `target_list.csv` و `pipeline_stages.yml` را به کار می‌برد؛ `STORE=sql` از SQL Server استفاده می‌کند. هر دو همان ردیف‌ها را برمی‌گردانند: تاریخ‌ها به‌صورت رشته‌ی `YYYY-MM-DD` و متن خالی به‌صورت ""، دقیقاً همان‌طور که CSV داشت، پس بقیه‌ی سرور هیچ‌وقت نمی‌داند با کدام حرف می‌زند. fact bank، دیکشنری gap و پوشه‌های درخواست در هر دو حالت فایل می‌مانند: دست‌چین یا باینری‌اند.'],examples:["open"]},{id:"shape",h:"شکلی که هر دو store برمی‌گردانند",p:["`shape.js` قرارداد را نگه می‌دارد: ستون‌های ledger و recruiter با همان نام‌هایی که `ledger.csv` و `target_list.csv` همیشه داشتند، تا کلاینت هرگز نداند کدام store پشت API است. gap tagها در API یک فهرست با کاما هستند، هرچند SQL آن‌ها را به‌صورت ردیف‌های جداگانه نگه می‌دارد؛ `splitGapTags` ترتیبشان را حفظ می‌کند و خالی‌ها و تکراری‌ها را حذف می‌کند.","recruiter پوشه ندارد، پس idاش یک SHA-1 کوتاه از URL لینکدین است (برای هر نفر یکتا)، و اگر نبود از نام و شرکت. این همان قاعده‌ی درخواست‌ها را نگه می‌دارد: یک به‌روزرسانی هرگز به جای ردیف بستگی ندارد. مجموعه‌ی تست API برای هر store یک بار اجرا می‌شود، پس اگر روزی این دو شکل متفاوتی برمی‌گرداندند، یک تست می‌شکست."],examples:["columns","recruiterId"]},{id:"csv",h:"store از نوع CSV",p:["هر خواندن-تغییر-نوشتن در یک متد و به‌صورت synchronous اجرا می‌شود، پس دو درخواست در همین process نمی‌توانند بین خواندن و نوشتن قاطی شوند."],examples:["sync"]},{id:"sql",h:"store از نوع SQL",p:["درخواست تازه، gap tagهایش و اولین رویداد پیش‌نویسش در یک transaction می‌روند. تاریخ‌ها را خود SQL Server قالب‌بندی می‌کند (style 23)، پس هیچ تبدیل منطقه‌ی زمانی JavaScript هیچ‌وقت به آن‌ها دست نمی‌زند. مقداری که دیتابیس رد کند (تاریخ بد، خیلی طولانی، یک constraint) 400 می‌دهد، نه 500."],examples:["create","select","errors"]}],examples:{open:{title:{en:"Which store",fa:"کدام store"},lang:"javascript",file:"server/src/stores/index.js",from:"export async function openStore(cfg) {",lines:7},sync:{title:{en:"Why the CSV store needs no lock",fa:"چرا store CSV قفل لازم ندارد"},lang:"javascript",file:"server/src/stores/csvStore.js",from:"// Every read-modify-write here is synchronous",lines:2},create:{title:{en:"All of it, or none of it",fa:"همه‌اش، یا هیچ‌کدام"},lang:"javascript",file:"server/src/stores/sqlStore.js",from:"async createApplication(row) {",lines:13},select:{title:{en:"Dates formatted by SQL Server",fa:"تاریخ‌هایی که SQL Server قالب می‌دهد"},lang:"javascript",file:"server/src/stores/sqlStore.js",from:"function selectList(columns, alias) {",lines:13},errors:{title:{en:"The database said no: 400",fa:"دیتابیس گفت نه: 400"},lang:"javascript",file:"server/src/stores/sqlStore.js",from:"const VALIDATION_ERROR_NUMBERS",lines:4},columns:{title:{en:"One row shape for both stores",fa:"یک شکل ردیف برای هر دو store"},lang:"javascript",file:"server/src/stores/shape.js",from:"// The API's row shapes",to:"];"},recruiterId:{title:{en:"A recruiter id that is not a position",fa:"id برای recruiter که شماره‌ی ردیف نیست"},lang:"javascript",file:"server/src/stores/shape.js",from:"export function recruiterId(r) {",lines:4}},quiz:[{q:{en:'Why do both stores return dates as `YYYY-MM-DD` strings and empty text as ""?',fa:'چرا هر دو store تاریخ را به‌صورت رشته‌ی `YYYY-MM-DD` و متن خالی را "" برمی‌گردانند؟'},options:{en:["So the rest of the server never knows which store it talks to","Because SQL Server has no date type","To save space in the CSV"],fa:["تا بقیه‌ی سرور هرگز نداند با کدام store حرف می‌زند","چون SQL Server نوع تاریخ ندارد","برای صرفه‌جویی در جای CSV"]},answer:0,why:{en:"The CSV always had that shape, so the SQL store matches it exactly.",fa:"CSV همیشه همین شکل را داشت، پس store مربوط به SQL دقیقاً با آن جور می‌شود."}},{q:{en:"Why does every read-modify-write in the CSV store run synchronously?",fa:"چرا هر خواندن-تغییر-نوشتن در store مربوط به CSV هم‌گام اجرا می‌شود؟"},options:{en:["Because async file APIs do not exist on Windows","So two requests in the process can not interleave between the read and the write","To make the server faster"],fa:["چون APIهای ناهمگام فایل روی Windows وجود ندارند","تا دو درخواست در همین process نتوانند بین خواندن و نوشتن درهم شوند","تا سرور سریع‌تر شود"]},answer:1,why:{en:"With no await in between, Node can not run another request in the middle of the update.",fa:"وقتی میانش هیچ await نیست، Node نمی‌تواند درخواست دیگری را وسط به‌روزرسانی اجرا کند."}},{q:{en:"In the SQL store, a value the database refuses (a bad date, a constraint) answers with which status?",fa:"در store مربوط به SQL، مقداری که پایگاه داده رد می‌کند (تاریخ بد، یک constraint) با چه وضعیتی پاسخ می‌گیرد؟"},options:{en:["500, like any database error","423, like a locked file","400, because the error number is in a known list of validation errors"],fa:["500، مثل هر خطای پایگاه داده","423، مثل فایل قفل‌شده","400، چون شماره‌ی خطا در فهرست شناخته‌شده‌ی خطاهای اعتبارسنجی است"]},answer:2,why:{en:"It is the request that is wrong, not the server, so the caller gets 400 with the reason.",fa:"این درخواست است که اشتباه است، نه سرور، پس فرستنده 400 با دلیلش می‌گیرد."}}]},{id:"schema",group:"data",title:{en:"The SQL Server schema",fa:"schema در SQL Server"},files:["db/01-database.sql","db/02-service-login.sql","db/03-schema.sql","server/src/stores/migrate.js"],en:[{id:"scripts",h:"Numbered, idempotent scripts",p:["`01` creates the database, `03` the tables (creating only what is missing, so it re-runs safely, with later columns added by `ALTER TABLE` behind a check), `02` the login the dashboard connects as: read and write data only, no DDL; schema changes go through these scripts. The password is a sqlcmd variable, never in the file."],examples:["svc"]},{id:"rules",h:"The server's rules, again in the database",p:['The folder name allows the same characters the server does; a gap tag must be a short kebab-case slug (a free-text sentence once shredded 11 ledger rows into comma fragments), and the gap tags moved from one comma-joined column to a table of their own, in display order. Text columns are NOT NULL with "" as default, because the API has always used "" for an empty field.'],examples:["folder","slug"]},{id:"migrate",h:"From CSV, in one transaction",p:["`npm run migrate:sql` copies the CSV and YAML data into SQL Server in a single transaction, then compares every field, event, stage and recruiter, and the computed pipeline. It refuses a database that already has data unless told to replace it, and never changes the CSV files: they stay as the backup."],examples:["refuse"]},{id:"tables",h:"Tables",data:{kind:"tables",only:["Stages","Applications","ApplicationGapTags","PipelineEvents","Recruiters"]}}],fa:[{id:"scripts",h:"اسکریپت‌های شماره‌دار و idempotent",p:["`01` دیتابیس را می‌سازد، `03` جدول‌ها را (فقط چیزی را که نیست، پس دوباره اجرا کردنش بی‌خطر است، و ستون‌های بعدی با `ALTER TABLE` پشت یک چک اضافه می‌شوند)، `02` loginی که داشبورد با آن وصل می‌شود: فقط خواندن و نوشتن داده، بدون DDL؛ تغییر schema از همین اسکریپت‌ها می‌رود. رمز یک متغیر sqlcmd است، هیچ‌وقت در فایل."],examples:["svc"]},{id:"rules",h:"قانون‌های سرور، دوباره در دیتابیس",p:['اسم پوشه همان کاراکترهایی را قبول می‌کند که سرور؛ gap tag باید یک slug کوتاه kebab-case باشد (یک جمله‌ی آزاد یک بار ۱۱ ردیف ledger را به تکه‌های جداشده با ویرگول خرد کرد)، و gap tagها از یک ستون با ویرگول به جدول خودشان، به ترتیب نمایش، منتقل شدند. ستون‌های متنی NOT NULL با پیش‌فرض "" هستند، چون API همیشه برای فیلد خالی "" به کار برده.'],examples:["folder","slug"]},{id:"migrate",h:"از CSV، در یک transaction",p:["`npm run migrate:sql` داده‌ی CSV و YAML را در یک transaction به SQL Server کپی می‌کند، بعد هر فیلد، رویداد، مرحله و recruiter، و pipeline محاسبه‌شده را مقایسه می‌کند. دیتابیسی را که از قبل داده دارد رد می‌کند مگر گفته شود جایگزین کند، و هیچ‌وقت فایل‌های CSV را عوض نمی‌کند: به‌عنوان backup می‌مانند."],examples:["refuse"]},{id:"tables",h:"جدول‌ها",data:{kind:"tables",only:["Stages","Applications","ApplicationGapTags","PipelineEvents","Recruiters"]}}],examples:{svc:{title:{en:"Data only, no DDL",fa:"فقط داده، بدون DDL"},lang:"sql",file:"db/02-service-login.sql",from:"IF USER_ID(N'ledger_svc') IS NULL",lines:3},folder:{title:{en:"The folder name, checked here too",fa:"اسم پوشه، این‌جا هم چک می‌شود"},lang:"sql",file:"db/03-schema.sql",from:"Folder        NVARCHAR(150)",lines:4},slug:{title:{en:"Only short slugs",fa:"فقط slugهای کوتاه"},lang:"sql",file:"db/03-schema.sql",from:"-- Gap tags per application, in display order",lines:17},refuse:{title:{en:"Not into a database with data",fa:"نه در دیتابیسی که داده دارد"},lang:"javascript",file:"server/src/stores/migrate.js",from:"if (recordset[0].n > 0) {",lines:8}},quiz:[{q:{en:"Why can `03-schema.sql` be re-run safely on an existing database?",fa:"چرا `03-schema.sql` را می‌شود بی‌خطر روی پایگاه داده‌ی موجود دوباره اجرا کرد؟"},options:{en:["It creates only what is missing and adds later columns behind a check","It drops every table first","It runs inside the migration"],fa:["فقط چیزی را که نیست می‌سازد و ستون‌های بعدی را پشت یک بررسی اضافه می‌کند","اول همه‌ی جدول‌ها را drop می‌کند","داخل migration اجرا می‌شود"]},answer:0,why:{en:"Every CREATE and ALTER is guarded, so running it twice changes nothing.",fa:"هر CREATE و ALTER پشت یک شرط است، پس دو بار اجرا کردنش چیزی را عوض نمی‌کند."}},{q:{en:"Why may `ledger_svc`, the dashboard's login, read and write data but not change the schema?",fa:"چرا `ledger_svc`، login داشبورد، می‌تواند داده را بخواند و بنویسد ولی schema را نه؟"},options:{en:["Because SQL Server does not allow it","So schema changes only go through the numbered scripts, and a compromised app can not alter tables","Because the schema is read-only"],fa:["چون SQL Server اجازه نمی‌دهد","تا تغییر schema فقط از راه اسکریپت‌های شماره‌دار باشد و اپ آسیب‌دیده نتواند جدول‌ها را عوض کند","چون schema فقط‌خواندنی است"]},answer:1,why:{en:"Least privilege: the app needs data access only.",fa:"کمترین دسترسی: اپ فقط به داده نیاز دارد."}},{q:{en:"What does the migration do if the target database already has data?",fa:"اگر پایگاه داده‌ی مقصد از قبل داده داشته باشد، migration چه می‌کند؟"},options:{en:["Merges the CSV into it","Deletes the CSV files","Refuses, unless told to replace it"],fa:["CSV را با آن ادغام می‌کند","فایل‌های CSV را حذف می‌کند","رد می‌کند، مگر اینکه صریحاً گفته شود جایگزینش کند"]},answer:2,why:{en:"It never overwrites by accident and never touches the CSV, which stays as the backup.",fa:"هرگز تصادفی بازنویسی نمی‌کند و به CSV دست نمی‌زند، که به‌عنوان نسخه‌ی پشتیبان می‌ماند."}}]},{id:"reporting",group:"data",title:{en:"Views for other systems, and Power BI",fa:"viewها برای سیستم‌های دیگر، و Power BI"},files:["db/04-views.sql","db/05-reader-login.sql","db/06-report-views.sql","reports/LedgerDashboard.pbip"],en:[{id:"same",h:"The dashboard's numbers, in SQL",p:["`vApplicationCurrentStage`, `vFollowupsDue`, `vFunnelBySource` and `vGapTagStats` compute in SQL what the dashboard computes in JavaScript (the current stage, the 7-day follow-up rule, outcomes by source, gap tags against rejections), and give the same numbers. Control Panel's `ledgerdash-adapter` reads them.","`vFollowupsDue` is the same rule as the Pipeline board: a waiting stage, and more than 7 days since the newer of entering the stage and the last follow-up (`COALESCE(LastFollowupDate, StageSince)`). Writing it once in JavaScript and once in SQL is a deliberate copy, so another system can read the numbers without running Node, and the adapter's numbers match what the dashboard shows exactly."],examples:["current","due"]},{id:"reader",h:"A login that sees only the views",p:["`ledger_reader` can SELECT those views and nothing else, not even the tables: the views are owned by dbo like the tables they read, so ownership chaining lets them work without any grant on the tables.","Like the service login, its password is a sqlcmd variable passed on the command line, and re-running the script resets it. The views it reads leave out contact emails and recruiter names, so even this narrow login sees nothing personal beyond what the dashboard shows about the employer."],examples:["reader"]},{id:"rpt",h:"The rpt schema and the Power BI report",p:["`06` adds a reporting schema, `rpt`: model tables for the Power BI project in `reports/` (one row per application with every attribute a report slices by, plus events, gap tags and recruiters without names or profile URLs) and ready-made summaries for plain SQL. Weeks start on Monday whatever `DATEFIRST` the server has.","The reader gets `SELECT` on the whole `rpt` schema in one grant, so a new reporting view needs no new permission. Measures live in the Power BI model; the views only shape rows, which keeps the arithmetic in one place per tool."],examples:["kinds","week","rptGrant"]}],fa:[{id:"same",h:"عددهای داشبورد، در SQL",p:["`vApplicationCurrentStage`، `vFollowupsDue`، `vFunnelBySource` و `vGapTagStats` در SQL همان چیزی را حساب می‌کنند که داشبورد در JavaScript (مرحله‌ی فعلی، قانون پیگیری ۷ روزه، نتیجه بر اساس منبع، gap tagها در برابر ردشدن‌ها)، و همان عددها را می‌دهند. `ledgerdash-adapter` در Control Panel آن‌ها را می‌خواند.","`vFollowupsDue` همان قاعده‌ی تابلوی Pipeline است: مرحله‌ای در حالت انتظار، و بیش از ۷ روز از تازه‌ترینِ ورود به مرحله و آخرین follow-up (`COALESCE(LastFollowupDate, StageSince)`). نوشتنش یک بار در JavaScript و یک بار در SQL کپی‌ای عمدی است، تا سیستم دیگری بتواند عددها را بدون اجرای Node بخواند و عددهای adapter دقیقاً با آنچه داشبورد نشان می‌دهد یکی باشد."],examples:["current","due"]},{id:"reader",h:"loginی که فقط viewها را می‌بیند",p:["`ledger_reader` می‌تواند آن viewها را SELECT کند و هیچ چیز دیگر، حتی جدول‌ها را نه: مالک viewها مثل جدول‌هایی که می‌خوانند dbo است، پس ownership chaining آن‌ها را بدون هیچ grantی روی جدول‌ها به کار می‌اندازد.","مثل login سرویس، رمز آن هم یک متغیر sqlcmd است که در خط فرمان داده می‌شود، و اجرای دوباره‌ی اسکریپت آن را از نو تنظیم می‌کند. viewهایی که می‌خواند ایمیل contactها و نام recruiterها را کنار می‌گذارند، پس حتی این login محدود هم چیزی شخصی فراتر از آنچه داشبورد درباره‌ی کارفرما نشان می‌دهد نمی‌بیند."],examples:["reader"]},{id:"rpt",h:"schema rpt و گزارش Power BI",p:["`06` یک schema گزارش‌گیری اضافه می‌کند، `rpt`: جدول‌های مدل برای پروژه‌ی Power BI در `reports/` (یک ردیف برای هر درخواست با هر ویژگی‌ای که گزارش بر اساسش برش می‌زند، به‌علاوه‌ی رویدادها، gap tagها و recruiterها بدون اسم یا URL پروفایل) و خلاصه‌های آماده برای SQL ساده. هفته‌ها، هر `DATEFIRST`ی که سرور داشته باشد، از دوشنبه شروع می‌شوند.","reader با یک grant روی کل schema مربوط به `rpt` دسترسی `SELECT` می‌گیرد، پس یک view گزارشی تازه به مجوز تازه‌ای نیاز ندارد. measureها در مدل Power BI زندگی می‌کنند؛ viewها فقط ردیف‌ها را شکل می‌دهند، که محاسبه را برای هر ابزار در یک جا نگه می‌دارد."],examples:["kinds","week","rptGrant"]}],examples:{current:{title:{en:"The current stage in SQL",fa:"مرحله‌ی فعلی در SQL"},lang:"sql",file:"db/04-views.sql",from:"CREATE OR ALTER VIEW dbo.vApplicationCurrentStage AS",lines:8},due:{title:{en:"Follow-ups due, the same 7 days",fa:"پیگیری‌های لازم، همان ۷ روز"},lang:"sql",file:"db/04-views.sql",from:"CREATE OR ALTER VIEW dbo.vFollowupsDue AS",lines:8},reader:{title:{en:"Views only",fa:"فقط viewها"},lang:"sql",file:"db/05-reader-login.sql",from:"-- The views are owned by dbo",lines:6},kinds:{title:{en:"Two kinds of views",fa:"دو نوع view"},lang:"sql",file:"db/06-report-views.sql",from:"-- Two kinds of views:",lines:8},week:{title:{en:"Monday, whatever DATEFIRST is",fa:"دوشنبه، هر چه DATEFIRST باشد"},lang:"sql",file:"db/06-report-views.sql",from:"DATEADD(day, -((DATEPART(weekday, ev.SentDate)",lines:1},rptGrant:{title:{en:"The reader sees the rpt schema too",fa:"reader schema مربوط به rpt را هم می‌بیند"},lang:"sql",file:"db/06-report-views.sql",from:"IF USER_ID(N'ledger_reader') IS NOT NULL GRANT SELECT ON SCHEMA::rpt",lines:1}},quiz:[{q:{en:"How can `ledger_reader` read the views without any permission on the tables?",fa:"`ledger_reader` چطور بدون هیچ مجوزی روی جدول‌ها viewها را می‌خواند؟"},options:{en:["Ownership chaining: the views and the tables have the same owner, dbo","The views copy the data into new tables","It connects as sa"],fa:["ownership chaining: viewها و جدول‌ها مالک یکسانی دارند، dbo","viewها داده را در جدول‌های تازه کپی می‌کنند","با sa وصل می‌شود"]},answer:0,why:{en:"When the owner is the same, SQL Server does not check permissions on the underlying tables.",fa:"وقتی مالک یکسان است، SQL Server مجوزهای جدول‌های زیرین را بررسی نمی‌کند."}},{q:{en:"Why compute the current stage and the follow-up rule again in SQL views?",fa:"چرا مرحله‌ی فعلی و قاعده‌ی follow-up دوباره در viewهای SQL محاسبه می‌شوند؟"},options:{en:["Because the JavaScript version is wrong","So another system such as Control Panel's adapter gets the same numbers without running the dashboard","Because Power BI can not read tables"],fa:["چون نسخه‌ی JavaScript اشتباه است","تا سیستم دیگری مثل adapter کنترل پنل همان عددها را بدون اجرای داشبورد بگیرد","چون Power BI نمی‌تواند جدول بخواند"]},answer:1,why:{en:"The views give the same results as the dashboard, read directly from the database.",fa:"viewها همان نتیجه‌های داشبورد را مستقیماً از پایگاه داده می‌دهند."}},{q:{en:"Why do the rpt views compute weeks without relying on the server's `DATEFIRST`?",fa:"چرا viewهای rpt هفته‌ها را بدون تکیه بر `DATEFIRST` سرور حساب می‌کنند؟"},options:{en:["Because `DATEFIRST` is deprecated","To make the views faster","So weeks always start on Monday, whatever the server is configured with"],fa:["چون `DATEFIRST` منسوخ شده","تا viewها سریع‌تر شوند","تا هفته‌ها همیشه از دوشنبه شروع شوند، هر تنظیمی که سرور داشته باشد"]},answer:2,why:{en:"A setting that differs between servers would otherwise shift every weekly number.",fa:"در غیر این صورت تنظیمی که بین سرورها فرق دارد همه‌ی عددهای هفتگی را جابه‌جا می‌کرد."}}]}],i={project:e,repo:t,path:a,scan:s,groups:n,pages:r};export{i as default,n as groups,r as pages,a as path,e as project,t as repo,s as scan};
